      ret.nodeSeparation = this.nodeSeparation
      differentFromDefault = true
    }
    if (this.packingAspectRatio != 1.5) {
      ret.packingAspectRatio = this.packingAspectRatio
      differentFromDefault = true
    }
    if ((ret.edgeRoutingSettings = this.edgeRoutingSettings.toJSON())) {
      differentFromDefault = true
