export function getSettingsFromAncestor(geomGraph: GeomGraph): any {
  let p = geomGraph.parent as GeomGraph
  while (p) {
    if (p.layoutSettings) {
      return p.layoutSettings
    }
    p = p.parent as GeomGraph
  }
  return null
}

