export function compareNumbersDistEps(a: number, b: number): number {
  const c: number = a - b
  // The <= and >= here complement the < and > in Close(double, double).
  if (c <= -GeomConstants.distanceEpsilon) {
    return -1
  }

  if (c >= GeomConstants.distanceEpsilon) {
    return 1
  }

  return 0
}

