      StraightLineEdges.CreateSimpleEdgeCurveWithUnderlyingPolyline(edge)
      if (edge.label) {
        this.registerForUndo(edge.edge.label)
      }
    }

    const ep = EdgeLabelPlacement.constructorGA(this.graph(), Array.from(this.edgesToReroute))
    ep.run()
  }

