    const dro = objectWithEditedLabel.getAttr(AttributeRegistry.DrawingObjectIndex) as DrawingObject
    dro.labelText = innerText
    this.viewer.invalidate(objectWithEditedLabel.getAttr(AttributeRegistry.ViewerIndex))
  }

