  }

redo() {
    Assert.assert(this.canRedo)
    if (this.data instanceof Map) {
      for (const [e, v] of this.data) {
        for (const pair of v) {
          const attr = pair.new
          attr.rebind(e)
        }
      }
    } else if ('deletedEnts' in this.data) {
      for (const ent of this.data.deletedEnts) {
        if (ent instanceof Graph) {
