    if (!this.canUndo) return
    if (this.currentBridge.canUndo) {
      this.currentBridge.undo()
    } else {
      this.currentBridge.prev.undo()
    }

    if (this.currentBridge.prev) this.currentBridge = this.currentBridge.prev
  }

