export default class CurveLayer<DataT> extends Layer<Required<CurveLayerProps<DataT>>> {
  static layerName = 'CurveLayer'
  static defaultProps = defaultProps

  state!: {
    model?: Model
    startIndices: number[]
    numInstances: number
    segments: Uint16Array
  }

  getShaders() {
    return super.getShaders({vs, fs, modules: [project32, picking]})
  }

  initializeState() {
    this.getAttributeManager().addInstanced({
      instancePositions: {
        size: 8,
        // type: GL.DOUBLE,
        // fp64: true,
        transition: true,
        accessor: 'getControlPoints',
        shaderAttributes: {
          instancePositions1: {
            size: 4,
          },
          instancePositions2: {
            size: 4,
            elementOffset: 4,
          },
        },
      },
      instanceSegments: {
        size: 2,
        update: this._getSegments,
      },
      instanceTypes: {
        size: 1,
        type: GL.UNSIGNED_BYTE,
        accessor: 'getCurveType',
      },
      instanceWidths: {
        size: 1,
        transition: true,
        accessor: 'getWidth',
        defaultValue: 1,
      },
      instanceColors: {
        size: 4,
        transition: true,
        normalized: true,
        type: GL.UNSIGNED_BYTE,
        accessor: 'getColor',
        defaultValue: [0, 0, 0, 255],
      },
    })
  }

  updateState(params: UpdateParameters<this>) {
    super.updateState(params)

    const {props, changeFlags} = params

    if (changeFlags.dataChanged) {
      this.updateGeometry()
    }

    if (changeFlags.extensionsChanged) {
      const {gl} = this.context
      this.state.model?.delete()
      this.state.model = this._getModel(gl)
      this.getAttributeManager().invalidateAll()
    }
  }

  updateGeometry() {
    const {data, getResolution, getCurveType, getRange} = this.props
    const {iterable, objectInfo} = createIterable(data)
    const startIndices = [0]
    let numInstances = 0
    const segments = []

    for (const object of iterable) {
      objectInfo.index++
      const type = typeof getCurveType === 'function' ? getCurveType(object, objectInfo) : getCurveType
      const range = typeof getRange === 'function' ? getRange(object, objectInfo) : getRange
      const res =
        type === CURVE.Line ? 1 : Math.ceil(typeof getResolution === 'function' ? getResolution(object, objectInfo) : getResolution)
      numInstances += res
      const step = (range[1] - range[0]) / res
      startIndices.push(numInstances)
      for (let i = 0; i < res; i++) {
        segments.push(range[0] + step * i, step)
      }
    }

    this.setState({startIndices, numInstances, segments: new Float32Array(segments)})
  }

  draw({uniforms}: any) {
    const {widthUnits, widthScale, widthMinPixels, widthMaxPixels} = this.props

    this.state.model
      .setUniforms(uniforms)
      .setUniforms({
        widthUnits: UNIT[widthUnits],
        widthScale,
        widthMinPixels,
        widthMaxPixels,
      })
      .draw()
  }

  protected _getModel(gl: WebGLRenderingContext): Model {
    const positions = [0, -1, 1, -1, 1, 1, 0, 1]

    return new Model(gl, {
      ...this.getShaders(),
      id: this.props.id,
      geometry: new Geometry({
        drawMode: GL.TRIANGLE_FAN,
        vertexCount: 4,
        attributes: {
          positions: {size: 2, value: new Float32Array(positions)},
        },
      }),
      isInstanced: true,
    })
  }

  private _getSegments(attribute: any) {
    attribute.value = this.state.segments
  }
}

getShaders() {
    return super.getShaders({vs, fs, modules: [project32, picking]})
  }

initializeState() {
    this.getAttributeManager().addInstanced({
      instancePositions: {
        size: 8,
        // type: GL.DOUBLE,
        // fp64: true,
        transition: true,
        accessor: 'getControlPoints',
        shaderAttributes: {
          instancePositions1: {
            size: 4,
          },
          instancePositions2: {
            size: 4,
            elementOffset: 4,
          },
        },
      },
      instanceSegments: {
        size: 2,
        update: this._getSegments,
      },
      instanceTypes: {
        size: 1,
        type: GL.UNSIGNED_BYTE,
        accessor: 'getCurveType',
      },
      instanceWidths: {
        size: 1,
        transition: true,
        accessor: 'getWidth',
        defaultValue: 1,
      },
      instanceColors: {
        size: 4,
        transition: true,
        normalized: true,
        type: GL.UNSIGNED_BYTE,
        accessor: 'getColor',
        defaultValue: [0, 0, 0, 255],
      },
    })
  }

updateState(params: UpdateParameters<this>) {
    super.updateState(params)

    const {props, changeFlags} = params

    if (changeFlags.dataChanged) {
      this.updateGeometry()
    }

    if (changeFlags.extensionsChanged) {
      const {gl} = this.context
      this.state.model?.delete()
      this.state.model = this._getModel(gl)
      this.getAttributeManager().invalidateAll()
    }
  }

updateGeometry() {
    const {data, getResolution, getCurveType, getRange} = this.props
    const {iterable, objectInfo} = createIterable(data)
    const startIndices = [0]
    let numInstances = 0
    const segments = []

    for (const object of iterable) {
      objectInfo.index++
      const type = typeof getCurveType === 'function' ? getCurveType(object, objectInfo) : getCurveType
      const range = typeof getRange === 'function' ? getRange(object, objectInfo) : getRange
      const res =
        type === CURVE.Line ? 1 : Math.ceil(typeof getResolution === 'function' ? getResolution(object, objectInfo) : getResolution)
      numInstances += res
      const step = (range[1] - range[0]) / res
      startIndices.push(numInstances)
      for (let i = 0; i < res; i++) {
        segments.push(range[0] + step * i, step)
      }
    }

    this.setState({startIndices, numInstances, segments: new Float32Array(segments)})
