        defaultValue: [0, 0, 0, 255],
      },
      instanceLineWidths: {
        size: 1,
        transition: true,
        accessor: 'getLineWidth',
        defaultValue: 1,
      },
      instanceShapes: {
        size: 1,
        type: GL.UNSIGNED_BYTE,
        accessor: 'getShape',
      },
      instancePickingColors: {
        size: 3,
        type: GL.UNSIGNED_BYTE,
        accessor: 'getPickingColor',
      },
    })
  }

updateState(params: UpdateParameters<this>) {
    super.updateState(params)

    const {props, oldProps, changeFlags} = params
    let modelChanged = false

    if (changeFlags.extensionsChanged) {
      const {gl} = this.context
      this.state.model?.delete()
      this.state.model = this._getModel(gl)
      this.getAttributeManager().invalidateAll()
      modelChanged = true
    }

    if (modelChanged || props.highlightColors !== oldProps.highlightColors) {
      const depthHighlightColors = new Float32Array(16)
      for (let i = 0; i < 4; i++) {
        const color = props.highlightColors[i]
        if (color) {
          depthHighlightColors[i * 4] = color[0] / 255
          depthHighlightColors[i * 4 + 1] = color[1] / 255
          depthHighlightColors[i * 4 + 2] = color[2] / 255
          depthHighlightColors[i * 4 + 3] = Number.isFinite(color[3]) ? color[3] / 255 : 1
        }
      }
      this.state.model.setUniforms({depthHighlightColors})
    }
  }

protected _getModel(gl: WebGLRenderingContext): Model {
    // a square that minimally cover the unit circle
    const positions = [-1, -1, 1, -1, 1, 1, -1, 1]

    return new Model(gl, {
      ...this.getShaders(),
      id: this.props.id,
      geometry: new Geometry({
        drawMode: GL.TRIANGLE_FAN,
        vertexCount: 4,
        attributes: {
          positions: {size: 2, value: new Float32Array(positions)},
        },
      }),
      isInstanced: true,
    })
  }

export enum SHAPE {
  Rectangle = 0,
  Oval = 1,
  Diamond = 2,
}

export function getEdgeLayer(props: EdgeLayerProps, style: ParsedGraphEdgeLayerStyle): Layer {

  return new CurveLayer<CurveClip>(props, {
    id: `${props.id}-edge`,
    data: props.data,
    getCurveType,
    getControlPoints,
    getRange: (d: CurveClip) => {
      return [d.startPar, d.endPar]
    },
    widthUnits: 'pixels',
    // one vertex per 4 pixels
    getResolution: (d: CurveClip) => {
      return d.curve.length * props.resolution
    },
    // @ts-ignore
    clipByInstance: false,

    extensions: [
      new GraphStyleExtension({
        overrideProps: {
          opacity: style.opacity,
          getWidth: style.strokeWidth,
          getColor: style.strokeColor,
        },
      }),
    ],
  })
}

export function getArrowHeadLayer(
  props: IconLayerProps<{
    tip: Point
    edge: Edge
    base: Point
  }>,
  style: ParsedGraphEdgeLayerStyle,
): Layer {
  return new IconLayer<{
    tip: Point
    edge: Edge
    base: Point
  }>({
    ...props,
    id: `${props.id}-arrowhead`,
    iconAtlas: getIconAtlas(),
    iconMapping,
    getPosition: (d) => [d.tip.x, d.tip.y],
    getColor: (d) => getEdgeColor(d.edge),
    getIcon: (d) => getEdgeType(d.edge),
    getSize: (d) => getArrowSize(d.tip, d.base),
    getAngle: (d) => getArrowAngle(d.tip, d.base),
    billboard: false,
    sizeUnits: 'common',
    extensions: [
      new GraphStyleExtension({
        overrideProps: {
          opacity: style.opacity,
          sizeScale: style.arrowSize,
          getColor: style.arrowColor,
        },
      }),
    ],
  })
}

export function getEdgeLabelLayer(props: TextLayerProps<GeomLabel>, style: ParsedGraphEdgeLayerStyle): Layer {
  return new TextLayer<GeomLabel>(props, {
    id: `${props.id}-edge-label`,
    getText: getLabelText,
    getSize: getLabelSize,
    getColor: getLabelColor,
    getPosition: (d: GeomLabel) => [d.center.x, d.center.y],
    sizeUnits: 'common',
    characterSet: 'auto',

    extensions: [
      new GraphStyleExtension({
        overrideProps: {
          opacity: style.opacity,
          sizeScale: style.labelSize,
          getColor: style.labelColor,
        },
      }),
    ],
  })
}

function getCurveType(cc: CurveClip): CURVE {
  if (cc.curve instanceof Ellipse) {
    return CURVE.Arc
  }
  if (cc.curve instanceof BezierSeg) {
    return CURVE.Bezier
  }
  return CURVE.Line
}

function getControlPoints(cc: CurveClip): number[] {
  const c = cc.curve;
  if (c instanceof Ellipse) {
    return [c.center, c.aAxis, c.bAxis].flatMap(pointToArray)
  }
  if (c instanceof BezierSeg) {
    return c.b.flatMap(pointToArray)
  }
  return [c.start, c.end].flatMap(pointToArray)
}

function pointToArray(p: Point): [number, number] {
  return [p.x, p.y]
}

function getEdgeColor(e: Edge): [number, number, number] {
  const drawinEdge = getDrawingObj<DrawingEdge>(e)
  if (drawinEdge) {
    const color = drawinEdge.color
    if (color) return [color.R, color.G, color.B]
  }
  return [0, 0, 0]
}

function getEdgeType(e: Edge): string {
  return 'triangle-n'
}

function getArrowSize(tip: Point, end: Point): number {
  const dx = tip.x - end.x
  const dy = tip.y - end.y
  return Math.sqrt(dx * dx + dy * dy)
}

function getArrowAngle(tip: Point, end: Point): number {
  const dx = tip.x - end.x
  const dy = tip.y - end.y
  return (Math.atan2(dy, dx) / Math.PI) * 180
}

function getLabelText(l: GeomLabel): string {
  return getDrawingObj<DrawingEdge>(l.parent.entity).labelText
}

function getLabelSize(l: GeomLabel): number {
  return getDrawingObj<DrawingEdge>(l.parent.entity).fontsize
}

function getLabelColor(l: GeomLabel): [number, number, number] {
  const color = getDrawingObj<DrawingEdge>(l.parent.entity).labelfontcolor
  if (color) {
    return [color.R, color.G, color.B]
  }
  return [0, 0, 0]
}

function getDrawingObj<T extends DrawingObject>(e: Entity): T {
  return DrawingObject.getDrawingObj(e) as T
}

export function getNodeLayers(props: NodeLayerProps, style: ParsedGraphNodeLayerStyle): LayersList {
  return [
    new GeometryLayer<GeomNode>(props, {
      id: `${props.id}-node-boundary`,
      lineWidthUnits: 'pixels',
      getPosition: getNodeCenter,
      getSize: (e: GeomNode) => [e.boundingBox.width, e.boundingBox.height],
      getShape: (e: GeomNode) => getShapeFromNode(e.node),
      cornerRadius: getCornerRadius((props.data as GeomNode[])[0]),
      getLineColor: getNodeColor,
      getFillColor: getNodeFillColor,

      extensions: [
        new GraphStyleExtension({
          overrideProps: {
            opacity: style.opacity,
            sizeScale: style.size,
            getFillColor: style.fillColor,
            getLineWidth: style.strokeWidth,
            getLineColor: style.strokeColor,
          },
        }),
      ],
    }),

    new TextLayer<GeomNode>(props, {
      id: `${props.id}-node-label`,
      getPosition: getLabelPosition,
      getText: getLabelText,
      getSize: getLabelSize,
      getColor: getNodeColor,
      billboard: false,
      sizeUnits: 'common',
      characterSet: 'auto',

      extensions: [
        new GraphStyleExtension({
          overrideProps: {
            opacity: style.opacity,
            getColor: style.labelColor,
            sizeScale: style.labelSize,
          },
        }),
      ],
    }),
  ]
}

function getNodeCenter(n: GeomNode, {index, data}: any): Position {
  return [n.center.x, n.center.y, 1 - index / data.length]
}

function getLabelPosition(n: GeomNode, context: any): Position {
  if (n instanceof GeomGraph) {
    const box = n.boundingBox
    return [box.center.x, box.bottom + (<GeomGraph>n).labelSize.height / 2 + 2]
  }
  return getNodeCenter(n, context)
}

function getLabelText(n: GeomNode): string {
  const drawingNode = getDrawingObj<DrawingNode>(n.node)
  return drawingNode.labelText
}

function getLabelSize(n: GeomNode): number {
  const drawingNode = getDrawingObj<DrawingNode>(n.node)
  return drawingNode.fontsize
}

function getCornerRadius(n: GeomNode): number {
  if (!n) return 0
  const drawingNode = getDrawingObj<DrawingNode>(n.node)
  return drawingNode.xRad
}

function getNodeColor(e: GeomNode): [number, number, number, number] {
  const drawingNode = getDrawingObj<DrawingNode>(e.node)
  if (drawingNode) {
    const color = drawingNode.pencolor
    if (color) return [color.R, color.G, color.B, color.A]
  }
  return [0, 0, 0, 255]
}

function getNodeFillColor(e: GeomNode): [number, number, number, number] {
  const drawingNode = getDrawingObj<DrawingNode>(e.node)
  if (drawingNode) {
    const color = drawingNode.fillColor
    if (color) return [color.R, color.G, color.B, color.A]
  }
  return [255, 255, 255, 255]
}

function getDrawingObj<T extends DrawingObject>(e: Entity): T {
  return DrawingObject.getDrawingObj(e) as T
}

