  return {
    zoom: layer.context.viewport.zoom
  }
}

function evaluateProp(
  propName: string,
  interpolator: ValueOrInterpolator<unknown>,
  context: InterpolatorContext,
  originalValue: unknown
) {
  let value: unknown
  if (typeof interpolator === 'function') {
    value = interpolator(context)
  } else {
    value = interpolator
