export function measureTextSize(str: string, opts: Partial<TextMeasurerOptions>): Size {
  if (!str) {
    return new Size(0, 0)
  }
  const lines = str.split('\n')
  const w = lines.map((s) => s.length * 15).reduce((a: number, b: number) => Math.max(a, b), 0)
