export function edgeString(e: GeomEdge, edgesAsArrays: boolean): string {
  const s = e.source.id + '->' + e.target.id
  return s + ', curve(' + (edgesAsArrays ? interpolateEdgeAsString() : SvgDebugWriter.curveString(e.curve)) + ')'
