    this.initialize(verticesToLayers)
  }

initialize(verticesToLayers: number[]) {
    this.y = verticesToLayers
    this.verticesToX = null
    this.layers = null
  }

DropEmptyLayers(): LayerArrays {
    const drop = new Array<number>(this.Layers.length)
    let dropVal = 0
