      if (westMostAnchor != null) {
        this.thinRightNodes.push(LineSegment.mkLinePXY(westMostAnchor.origin, this.originalGraph.right, westMostAnchor.y).pNodeOverICurve())
      }

      uOffset++
    }

    // if (Routing.db) {
