      switch (p.tag) {
        case 'bezier':
          curve.addSegment(BezierSeg.fromJSON(p.segData))
          break
        case 'ellipse':
          curve.addSegment(Ellipse.fromJSON(p.segData))
          break
        case 'lineSegment':
          curve.addSegment(LineSegment.fromJSON(p.segData))
          break
        default:
          throw new Error('not implemented')
