  getParameterAtLength(length: number) {
    //todo: slow version!
    const eps = 0.001

    let l = this.parStart
    let u = this.parEnd
    const lenplus = length + eps
    const lenminsu = length - eps
    while (u - l > GeomConstants.distanceEpsilon) {
      const m = 0.5 * (u + l)
      const len = this.lengthPartial(this.parStart, m)
      if (len > lenplus) u = m
