    for (const b of boxes) {
      const verts = allVerticesOfParall(b)
      for (const v of verts) {
        const x = v.x
        const y = v.y
        if (firstTime) {
          firstTime = false
          minx = maxx = x
          miny = maxy = y
        } else {
          if (x < minx) {
            minx = x
          } else if (x > maxx) {
            maxx = x
          }
          if (y < miny) {
            miny = y
          } else if (y > maxy) {
            maxy = y
          }
