        if (y.color === RBColor.Red) {
          x.parent.color = RBColor.Black
          y.color = RBColor.Black
          x.parent.parent.color = RBColor.Red
          x = x.parent.parent
        } else {
          if (x === x.parent.right) {
            x = x.parent
            this.leftRotate(x)
          }
          x.parent.color = RBColor.Black
          x.parent.parent.color = RBColor.Red
          this.rightRotate(x.parent.parent)
