      } else {
        const y: RBNode<T> = x.parent.parent.left
        if (y.color === RBColor.Red) {
          x.parent.color = RBColor.Black
          y.color = RBColor.Black
          x.parent.parent.color = RBColor.Red
          x = x.parent.parent
        } else {
          if (x === x.parent.left) {
            x = x.parent
            this.rightRotate(x)
          }
          x.parent.color = RBColor.Black
          x.parent.parent.color = RBColor.Red
          this.leftRotate(x.parent.parent)
        }
