  const cdDel = d.sub(c).div(n)
  let dist = b.sub(c).length
  for (let i = 0; i <= n; i++) {
    const p = a.add(abDel.mul(i))
    for (let j = 0; j <= n; j++) {
      const q = c.add(cdDel.mul(j))
