    const splitDirection: Dim = this.Dimension(Dim.Horizontal) > this.Dimension(Dim.Vertical) ? Dim.Horizontal : Dim.Vertical
    const nonSplitDirection: Dim = splitDirection == Dim.Horizontal ? Dim.Vertical : Dim.Horizontal
    const n = this.Size()
