    let b: number[] = null
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (i != j) {
          const c: Disc = Disc.constructorPP(points[i], points[j])
          if (c.ContainsPN(points, [i, j])) {
            if (mc == null || mc.Radius > c.Radius) {
              mc = c
              b = [i, j]
            }
          }
        }

        for (let k = 0; k < n; k++) {
