            const c3: Disc = Disc.constructorPPP(points[i], points[j], points[k])
            if (c3.ContainsPN(points, [i, j, k])) {
              if (mc == null || mc.Radius > c3.Radius) {
                mc = c3
                b = [i, j, k]
              }
            }
