            yield node.UserData
          }
        } else {
          stack.push(node.left)
          stack.push(node.right)
        }
      }
    }
  }

  // returns all items for which the rectangle contains the point
  *AllHitItems_(point: P): IterableIterator<T> {
    const stack = new Stack<RectangleNode<T, P>>()
    stack.push(this)
    while (stack.size > 0) {
