export class LinkedPointSplitter {
  //

  // no two horizontal segs overlap, but they can share an end point
  // no two vertical segs overlap, but they can share an end point
  constructor(horizontalPoints: Array<LinkedPoint>, verticalPoints: Array<LinkedPoint>) {
    this.VerticalPoints = verticalPoints
    this.HorizontalPoints = horizontalPoints
  }

  HorizontalPoints: Array<LinkedPoint>

  VerticalPoints: Array<LinkedPoint>
  SplitPoints() {
    if (this.VerticalPoints.length === 0 || this.HorizontalPoints.length === 0) {
      return
    }

    // there will be no intersections
    this.InitEventQueue()
    this.ProcessEvents()
  }

  ProcessEvents() {
    while (!this.Queue.IsEmpty()) {
      const t = {priority: 0}
      const linkedPoint = this.Queue.DequeueAndGetPriority(t)
      this.ProcessEvent(linkedPoint, t.priority)
    }
  }

  ProcessEvent(linkedPoint: LinkedPoint, z: number) {
    if (closeDistEps(linkedPoint.Next.Point.x, linkedPoint.Point.x)) {
      if (z === LinkedPointSplitter.Low(linkedPoint)) {
        this.ProcessLowLinkedPointEvent(linkedPoint)
      } else {
        this.ProcessHighLinkedPointEvent(linkedPoint)
      }
    } else {
      this.IntersectWithTree(linkedPoint)
    }
  }

  IntersectWithTree(horizontalPoint: LinkedPoint) {
    let right: number
    let left: number
    let xAligned: boolean
    /*Assert.assert(closeDistEps(horizontalPoint.Y, horizontalPoint.Next.Y))*/
    const y = horizontalPoint.Y
    if (horizontalPoint.Point.x < horizontalPoint.Next.Point.x) {
      left = horizontalPoint.Point.x
      right = horizontalPoint.Next.Point.x
      xAligned = true
    } else {
      right = horizontalPoint.Point.x
      left = horizontalPoint.Next.Point.x
      xAligned = false
    }

    if (xAligned) {
      for (
        let node = this.tree.findFirst((p) => left <= p.Point.x);
        node != null && node.item.Point.x <= right;
        node = this.tree.next(node)
      ) {
        const p = new Point(node.item.Point.x, y)
        horizontalPoint = LinkedPointSplitter.TrySplitHorizontalPoint(horizontalPoint, p, true)
        LinkedPointSplitter.TrySplitVerticalPoint(node.item, p)
      }
    } else {
      for (
        let node = this.tree.findLast((p) => p.Point.x <= right);
        node != null && node.item.Point.x >= left;
        node = this.tree.previous(node)
      ) {
        const p = new Point(node.item.Point.x, y)
        horizontalPoint = LinkedPointSplitter.TrySplitHorizontalPoint(horizontalPoint, p, false)
        LinkedPointSplitter.TrySplitVerticalPoint(node.item, p)
      }
    }
  }

  static TrySplitVerticalPoint(linkedPoint: LinkedPoint, point: Point) {
    /*Assert.assert(closeDistEps(linkedPoint.X, linkedPoint.Next.X))*/
    if (
      LinkedPointSplitter.Low(linkedPoint) + GeomConstants.distanceEpsilon < point.y &&
      point.y + GeomConstants.distanceEpsilon < LinkedPointSplitter.High(linkedPoint)
    ) {
      linkedPoint.SetNewNext(point)
    }
  }

  static TrySplitHorizontalPoint(horizontalPoint: LinkedPoint, point: Point, xAligned: boolean): LinkedPoint {
    /*Assert.assert(closeDistEps(horizontalPoint.Y, horizontalPoint.Next.Y))*/
    if (
      (xAligned &&
        horizontalPoint.X + GeomConstants.distanceEpsilon < point.x &&
        point.x + GeomConstants.distanceEpsilon < horizontalPoint.Next.X) ||
      (!xAligned &&
        horizontalPoint.Next.X + GeomConstants.distanceEpsilon < point.x &&
        point.x + GeomConstants.distanceEpsilon < horizontalPoint.X)
    ) {
      horizontalPoint.SetNewNext(point)
      return horizontalPoint.Next
    }

    return horizontalPoint
  }

  ProcessHighLinkedPointEvent(linkedPoint: LinkedPoint) {
    this.tree.remove(linkedPoint)
  }

  tree: RBTree<LinkedPoint> = new RBTree<LinkedPoint>((a, b) => compareNumbers(a.Point.x, b.Point.x))

  ProcessLowLinkedPointEvent(linkedPoint: LinkedPoint) {
    this.tree.insert(linkedPoint)
  }

  InitEventQueue() {
    this.Queue = new GenericBinaryHeapPriorityQueue<LinkedPoint>(compareNumbers)
    for (const vertPoint of this.VerticalPoints) {
      this.Queue.Enqueue(vertPoint, LinkedPointSplitter.Low(vertPoint))
    }

    // a horizontal point will appear of the queue after a vertical point
    // with the same coordinate low coorinate
    for (const horizPoint of this.HorizontalPoints) {
      this.Queue.Enqueue(horizPoint, horizPoint.Point.y)
    }
  }

  static Low(vertPoint: LinkedPoint): number {
    return Math.min(vertPoint.Point.y, vertPoint.Next.Point.y)
  }

  static High(vertPoint: LinkedPoint): number {
    return Math.max(vertPoint.Point.y, vertPoint.Next.Point.y)
  }

  Queue: GenericBinaryHeapPriorityQueue<LinkedPoint>
}

constructor(horizontalPoints: Array<LinkedPoint>, verticalPoints: Array<LinkedPoint>) {
    this.VerticalPoints = verticalPoints
    this.HorizontalPoints = horizontalPoints
  }

SplitPoints() {
    if (this.VerticalPoints.length === 0 || this.HorizontalPoints.length === 0) {
      return
    }

    // there will be no intersections
    this.InitEventQueue()
    this.ProcessEvents()
  }

ProcessEvents() {
    while (!this.Queue.IsEmpty()) {
      const t = {priority: 0}
      const linkedPoint = this.Queue.DequeueAndGetPriority(t)
      this.ProcessEvent(linkedPoint, t.priority)
    }
  }

ProcessEvent(linkedPoint: LinkedPoint, z: number) {
    if (closeDistEps(linkedPoint.Next.Point.x, linkedPoint.Point.x)) {
      if (z === LinkedPointSplitter.Low(linkedPoint)) {
        this.ProcessLowLinkedPointEvent(linkedPoint)
      } else {
        this.ProcessHighLinkedPointEvent(linkedPoint)
      }
    } else {
      this.IntersectWithTree(linkedPoint)
    }
  }

IntersectWithTree(horizontalPoint: LinkedPoint) {
    let right: number
    let left: number
    let xAligned: boolean
    /*Assert.assert(closeDistEps(horizontalPoint.Y, horizontalPoint.Next.Y))*/
    const y = horizontalPoint.Y
    if (horizontalPoint.Point.x < horizontalPoint.Next.Point.x) {
      left = horizontalPoint.Point.x
      right = horizontalPoint.Next.Point.x
      xAligned = true
    } else {
      right = horizontalPoint.Point.x
      left = horizontalPoint.Next.Point.x
      xAligned = false
    }

    if (xAligned) {
      for (
        let node = this.tree.findFirst((p) => left <= p.Point.x);
        node != null && node.item.Point.x <= right;
        node = this.tree.next(node)
      ) {
        const p = new Point(node.item.Point.x, y)
        horizontalPoint = LinkedPointSplitter.TrySplitHorizontalPoint(horizontalPoint, p, true)
        LinkedPointSplitter.TrySplitVerticalPoint(node.item, p)
      }
    } else {
      for (
        let node = this.tree.findLast((p) => p.Point.x <= right);
        node != null && node.item.Point.x >= left;
        node = this.tree.previous(node)
      ) {
        const p = new Point(node.item.Point.x, y)
        horizontalPoint = LinkedPointSplitter.TrySplitHorizontalPoint(horizontalPoint, p, false)
        LinkedPointSplitter.TrySplitVerticalPoint(node.item, p)
      }
    }
  }

static TrySplitVerticalPoint(linkedPoint: LinkedPoint, point: Point) {
    /*Assert.assert(closeDistEps(linkedPoint.X, linkedPoint.Next.X))*/
    if (
      LinkedPointSplitter.Low(linkedPoint) + GeomConstants.distanceEpsilon < point.y &&
      point.y + GeomConstants.distanceEpsilon < LinkedPointSplitter.High(linkedPoint)
    ) {
      linkedPoint.SetNewNext(point)
    }
  }

static TrySplitHorizontalPoint(horizontalPoint: LinkedPoint, point: Point, xAligned: boolean): LinkedPoint {
    /*Assert.assert(closeDistEps(horizontalPoint.Y, horizontalPoint.Next.Y))*/
    if (
      (xAligned &&
        horizontalPoint.X + GeomConstants.distanceEpsilon < point.x &&
        point.x + GeomConstants.distanceEpsilon < horizontalPoint.Next.X) ||
      (!xAligned &&
        horizontalPoint.Next.X + GeomConstants.distanceEpsilon < point.x &&
        point.x + GeomConstants.distanceEpsilon < horizontalPoint.X)
    ) {
      horizontalPoint.SetNewNext(point)
      return horizontalPoint.Next
    }

    return horizontalPoint
  }

ProcessHighLinkedPointEvent(linkedPoint: LinkedPoint) {
    this.tree.remove(linkedPoint)
  }

ProcessLowLinkedPointEvent(linkedPoint: LinkedPoint) {
    this.tree.insert(linkedPoint)
  }

InitEventQueue() {
    this.Queue = new GenericBinaryHeapPriorityQueue<LinkedPoint>(compareNumbers)
    for (const vertPoint of this.VerticalPoints) {
      this.Queue.Enqueue(vertPoint, LinkedPointSplitter.Low(vertPoint))
    }

    // a horizontal point will appear of the queue after a vertical point
    // with the same coordinate low coorinate
    for (const horizPoint of this.HorizontalPoints) {
      this.Queue.Enqueue(horizPoint, horizPoint.Point.y)
    }
  }

static Low(vertPoint: LinkedPoint): number {
    return Math.min(vertPoint.Point.y, vertPoint.Next.Point.y)
  }

static High(vertPoint: LinkedPoint): number {
    return Math.max(vertPoint.Point.y, vertPoint.Next.Point.y)
  }

export class LongestNudgedSegment extends SegmentBase {
  constructor(variable: number) {
    super()
    this.Id = variable
  }

  // has to be North or East

  CompassDirection: Direction = Direction.None

  // the segment can go only North or East independently of the edge directions
  edges: Array<PathEdge> = new Array<PathEdge>()

  start: Point

  end: Point

  get Start(): Point {
    return this.start
  }

  get End(): Point {
    return this.end
  }

  // the list of edges holding the same offset and direction

  get Edges(): Array<PathEdge> {
    return this.edges
  }

  AddEdge(edge: PathEdge) {
    if (this.Edges.length === 0) {
      let dir = CompassVector.VectorDirectionPP(edge.Source, edge.Target)
      switch (dir) {
        case Direction.South:
          dir = Direction.North
          break
        case Direction.West:
          dir = Direction.East
          break
      }

      this.CompassDirection = dir
      this.start = edge.Source
      this.end = edge.Source
      // does not matter; it will be fixed immediately
    }

    switch (this.CompassDirection) {
      case Direction.North:
        this.TryPointForStartAndEndNorth(edge.Source)
        this.TryPointForStartAndEndNorth(edge.Target)
        break
      case Direction.East:
        this.TryPointForStartAndEndEast(edge.Source)
        this.TryPointForStartAndEndEast(edge.Target)
        break
    }

    this.Edges.push(edge)
  }

  TryPointForStartAndEndNorth(p: Point) {
    if (p.y < this.start.y) {
      this.start = p
    } else if (p.y > this.end.y) {
      this.end = p
    }
  }

  TryPointForStartAndEndEast(p: Point) {
    if (p.x < this.start.x) {
      this.start = p
    } else if (p.x > this.end.x) {
      this.end = p
    }
  }

  _isFixed = false

  // the segments constraining "this" from the right

  get IsFixed(): boolean {
    return this._isFixed
  }
  set IsFixed(value: boolean) {
    this._isFixed = value
  }

  Id = -1

  // the maximal width of the edges

  public get Width(): number {
    let w = 0
    for (const e of this.edges) {
      w = Math.max(w, e.Width)
    }
    return w
  }

  GetLeftBound(): number {
    if (!this.IsFixed) {
      let lb = Number.NEGATIVE_INFINITY
      for (const edge of this.edges) {
        lb = Math.max(lb, edge.AxisEdge.LeftBound)
      }
      return lb
    }

    return this.CompassDirection === Direction.North ? this.Edges[0].Source.x : -this.Edges[0].Source.y
  }

  GetRightBound(): number {
    if (!this.IsFixed) {
      let rb = Number.POSITIVE_INFINITY
      for (const edge of this.edges) {
        rb = Math.min(rb, edge.AxisEdge.RightBound)
      }
      return rb
    }

    return this.Position()
  }

  Position(): number {
    return this.CompassDirection === Direction.North ? this.Edges[0].Source.x : -this.Edges[0].Source.y
  }

  IdealPosition = 0
}

