  // Such an edge can be, for example, a terminal edge going to a port.

  IsFixed = false

  get Source(): Point {
    return !this.Reversed ? this.AxisEdge.SourcePoint : this.AxisEdge.TargetPoint
  }

  get Target(): Point {
    return this.Reversed ? this.AxisEdge.SourcePoint : this.AxisEdge.TargetPoint
  }

