        // we have a cycle
        for (let px = previous.next; px !== pp.next; px = px.next) {
          pointsToPp.deleteP(px.point)
        }

        previous.next = pp.next
        pp.next.prev = previous
        progress = true
      } else {
        pointsToPp.set(pp.point, pp)
      }
    }

    return progress
  }

ReduceEdgeCrossings(): boolean {
    const cycleCollapser = new FlipSwitcher(this.metroGraphData)
    cycleCollapser.Run()

    for (const t of cycleCollapser.GetChangedHubs()) this.crossingsThatShouldBecomeHubs.add(t)
    // TimeMeasurer.DebugOutput("#reduced crossings = " + cycleCollapser.NumberOfReducedCrossings());
    return cycleCollapser.NumberOfReducedCrossings() > 0
  }

RemoveUnimportantCrossings(): boolean {
    let removed = false
    this.pointsToDelete = substractPointSets(this.foundCrossings, this.crossingsThatShouldBecomeHubs)
    for (const polyline of this.Polylines) {
      if (this.RemoveUnimportantCrossingsFromPolyline(polyline)) {
        removed = true
      }
    }
    return removed
  }

RemoveUnimportantCrossingsFromPolyline(polyline: Polyline): boolean {
    let removed = false
    for (let p = polyline.startPoint.next; p != null && p.next != null; p = p.next) {
      if (
        this.pointsToDelete.has(p.point) &&
        Point.getTriangleOrientation(p.prev.point, p.point, p.next.point) === TriangleOrientation.Collinear
      ) {
        // forget p
        const pp = p.prev
        const pn = p.next
        pp.next = pn
        pn.prev = pp
        p = pp
        removed = true
      }
    }

    return removed
  }

IntersectTwoEdges(a: PointPair, b: PointPair, splittingPoints: PointPairMap<Array<Point>>, tree: BinaryRTree<Point, Point>) {
    const x: Point = LineSegment.IntersectPPPP(a.first, a.second, b.first, b.second)
    if (x) {
      const vertex: Point = this.FindExistingVertexOrCreateNew(tree, x)
      if (this.AddVertexToSplittingList(a, splittingPoints, vertex) || this.AddVertexToSplittingList(b, splittingPoints, vertex)) {
        this.foundCrossings.add(vertex)
      }
    }
  }

FindExistingVertexOrCreateNew(tree: BinaryRTree<Point, Point>, x: Point): Point {
    const p = tree.RootNode.FirstHitNode(x)
    if (p != null) {
      return p.UserData
    }

    const rect = Rectangle.mkOnPoints([x])
    rect.pad(GeomConstants.intersectionEpsilon)
    tree.Add(rect, x)
    return x
  }

AddVertexToSplittingList(a: PointPair, splittingPoints: PointPairMap<Array<Point>>, intersectionPoint: Point): boolean {
    //let t: number
    //Assert.assert(Point.distToLineSegment(intersectionPoint, a.First, a.Second, /* out */ t) < ApproximateComparer.IntersectionEpsilon)
    if (!Curve.closeIntersectionPoints(intersectionPoint, a.first) && !Curve.closeIntersectionPoints(intersectionPoint, a.second)) {
      let list: Array<Point> = splittingPoints.get(a)
      if (!list) {
        list = new Array<Point>()
        splittingPoints.set(a, list)
      }

      if (!list.find((p) => p.equal(intersectionPoint))) {
        list.push(intersectionPoint)
        return true
      }
    }

    return false
  }

export class PointPairOrder {
  // array of metrolines for node u of edge u->v
  Metrolines: Array<Metroline> = new Array<Metroline>()

  orderFixed: boolean

  LineIndexInOrder: Map<Metroline, number>

  Add(metroline: Metroline) {
    this.Metrolines.push(metroline)
  }
}

Add(metroline: Metroline) {
    this.Metrolines.push(metroline)
  }

export class SdBoneEdge {
  VisibilityEdge: VisibilityEdge

  Source: SdVertex

  Target: SdVertex

  numberOfPassedPaths = 0

  constructor(visibilityEdge: VisibilityEdge, source: SdVertex, target: SdVertex) {
    this.VisibilityEdge = visibilityEdge
    this.Source = source
    this.Target = target
  }

  get TargetPoint(): Point {
    return this.Target.Point
  }

  get SourcePoint(): Point {
    return this.Source.Point
  }

  get IsOccupied(): boolean {
    return this.numberOfPassedPaths > 0
  }

  CrossedCdtEdges: Set<CdtEdge>

  get IsPassable(): boolean {
    return (
      this.Target.IsTargetOfRouting ||
      this.Source.IsSourceOfRouting ||
      this.VisibilityEdge.IsPassable == null ||
      this.VisibilityEdge.IsPassable()
    )
  }

  AddOccupiedEdge() {
    this.numberOfPassedPaths++
  }

  RemoveOccupiedEdge() {
    this.numberOfPassedPaths--
    /*Assert.assert(this.numberOfPassedPaths >= 0)*/
  }
}

constructor(visibilityEdge: VisibilityEdge, source: SdVertex, target: SdVertex) {
    this.VisibilityEdge = visibilityEdge
    this.Source = source
    this.Target = target
  }

AddOccupiedEdge() {
    this.numberOfPassedPaths++
  }

RemoveOccupiedEdge() {
    this.numberOfPassedPaths--
    /*Assert.assert(this.numberOfPassedPaths >= 0)*/
  }

export class SdShortestPath {
  VisibilityGraph: VisibilityGraph

  MakeTransparentShapesOfEdgeGeometry: (eg: GeomEdge) => Array<Shape>

  BundlingSettings: BundlingSettings

  geomEdges: GeomEdge[]

  ObstacleHierarchy: RectangleNode<Polyline, Point>

  vertexArray: SdVertex[]

  cdt: Cdt

  Gates: Set<CdtEdge>

  EdgesToRoutes: Map<GeomEdge, Array<SdBoneEdge>> = new Map<GeomEdge, Array<SdBoneEdge>>()

  EdgesToRouteSources: Map<GeomEdge, SdVertex> = new Map<GeomEdge, SdVertex>()

  CurrentEdgeGeometry: GeomEdge

  VisibilityVerticesToSdVerts: Map<VisibilityVertex, SdVertex>

  LengthCoefficient: number

  Queue: GenericBinaryHeapPriorityQueue<SdVertex>

  LowestCostToTarget: number

  ClosestTargetVertex: SdVertex

  capacityOverlowPenaltyMultiplier: number

  sourceLoosePoly: Polyline

  targetLoosePoly: Polyline

  constructor(makeTransparentShapesOfEdgeGeometryAndGetTheShapes: (e: GeomEdge) => Array<Shape>, cdt: Cdt, gates: Set<CdtEdge>) {
    this.MakeTransparentShapesOfEdgeGeometry = makeTransparentShapesOfEdgeGeometryAndGetTheShapes
    this.cdt = cdt
    this.Gates = gates
  }

  CreateGraphElements() {
    for (const sdVertex of this.vertexArray) {
      const vv = sdVertex.VisibilityVertex
      for (const vEdge of vv.InEdges) {
        const boneEdge = new SdBoneEdge(
          vEdge,
          this.VisibilityVerticesToSdVerts.get(vEdge.Source),
          this.VisibilityVerticesToSdVerts.get(vEdge.Target),
        )
        const otherSdVertex = this.VisibilityVerticesToSdVerts.get(vEdge.Source)
        sdVertex.InBoneEdges.push(boneEdge)
        otherSdVertex.OutBoneEdges.push(boneEdge)
      }
    }
  }

  CreateRoutingGraph() {
    this.vertexArray = []
    this.VisibilityVerticesToSdVerts = new Map<VisibilityVertex, SdVertex>()
    for (const v of this.VisibilityGraph.Vertices()) {
      const sdVert = new SdVertex(v)
      this.vertexArray.push(sdVert)
      this.VisibilityVerticesToSdVerts.set(v, sdVert)
    }

    this.CreateGraphElements()
  }

  // routing of the edges minimizing (ink+path length+capacity penalty)
  RouteEdges() {
    this.Initialize()
    this.RestoreCapacities()
    for (const geomEdge of this.geomEdges) {
      this.EdgesToRoutes.set(geomEdge, this.RouteEdge(geomEdge))
    }

    this.RerouteEdges()

    for (const geomEdge of this.geomEdges) this.SetEdgeGeometryCurve(geomEdge)
  }

  SetEdgeGeometryCurve(geomEdge: GeomEdge) {
    const poly = new Polyline()
    let curV = this.EdgesToRouteSources.get(geomEdge)
    poly.addPoint(curV.Point)
    for (const edge of this.EdgesToRoutes.get(geomEdge)) {
      if (edge.SourcePoint.equal(curV.Point)) {
        poly.addPoint(edge.TargetPoint)
        curV = edge.Target
      } else {
        poly.addPoint(edge.SourcePoint)
        curV = edge.Source
      }
    }

    geomEdge.curve = poly
    const isClusterSourcePort = geomEdge.sourcePort instanceof ClusterBoundaryPort
    if (isClusterSourcePort) SdShortestPath.ExtendPolylineStartToClusterBoundary(poly, (<ClusterBoundaryPort>geomEdge.sourcePort).Curve)

    const isClusterTargetPort = geomEdge.targetPort instanceof ClusterBoundaryPort
    if (isClusterTargetPort) SdShortestPath.ExtendPolylineEndToClusterBoundary(poly, (<ClusterBoundaryPort>geomEdge.targetPort).Curve)
  }

  static ExtendPolylineEndToClusterBoundary(poly: Polyline, curve: ICurve) {
    const par = curve.closestParameter(poly.end)
    poly.addPoint(curve.value(par))
  }

  static ExtendPolylineStartToClusterBoundary(poly: Polyline, curve: ICurve) {
    const par = curve.closestParameter(poly.start)
    poly.PrependPoint(curve.value(par))
  }

  RerouteEdges() {
    this.RestoreCapacities()
    for (const geomEdge of this.geomEdges) {
      const newRoute = this.RerouteEdge(geomEdge)
      this.EdgesToRoutes.set(geomEdge, newRoute)
    }
  }

  RestoreCapacities() {
    if (this.cdt != null) {
      this.cdt.RestoreEdgeCapacities()
    }
  }

  // Reroute edge
  RerouteEdge(geomEdge: GeomEdge): Array<SdBoneEdge> {
    const route = this.EdgesToRoutes.get(geomEdge)

    for (const edge of route) edge.RemoveOccupiedEdge()

    return this.RouteEdge(geomEdge)
  }

  RouteEdge(geomEdge: GeomEdge): Array<SdBoneEdge> {
    this.CurrentEdgeGeometry = geomEdge
    for (let i = 0; i < this.vertexArray.length; i++) {
      const sdv = this.vertexArray[i]
      sdv.SetPreviousToNull()
      sdv.IsTargetOfRouting = sdv.IsSourceOfRouting = false
    }

    const transparentShapes = this.MakeTransparentShapesOfEdgeGeometry(geomEdge)
    const ret = this.RouteEdgeWithGroups()
    for (const shape of transparentShapes) shape.IsTransparent = false
    return ret
  }

  RouteEdgeWithGroups(): Array<SdBoneEdge> {
    for (let i = 0; i < 2; i++) {
      this.SetLengthCoefficient()
      this.Queue = new GenericBinaryHeapPriorityQueue<SdVertex>()
      this.sourceLoosePoly = this.SetPortVerticesAndObstacles(this.CurrentEdgeGeometry.sourcePort, true)
      this.targetLoosePoly = this.SetPortVerticesAndObstacles(this.CurrentEdgeGeometry.targetPort, false)
      const ret: Array<SdBoneEdge> = this.RouteOnKnownSourceTargetVertices(
        this.CurrentEdgeGeometry.targetPort.Location.sub(this.CurrentEdgeGeometry.sourcePort.Location).normalize(),
        i === 0,
      )
      if (ret != null) {
        return ret
      }

      for (let j = 0; j < this.vertexArray.length; j++) {
        this.vertexArray[j].SetPreviousToNull()
      }
    }

    // SplineRouter.ShowVisGraph('./tmp/badVis.svg', this.VisibilityGraph, Array.from(this.ObstacleHierarchy.GetAllLeaves()), null, [
    //  LineSegment.mkPP(this.CurrentEdgeGeometry.sourcePort.Location, this.CurrentEdgeGeometry.targetPort.Location),
    // ])
    throw new Error()
  }

  RouteOnKnownSourceTargetVertices(pathDirection: Point, lookingForMonotonePath: boolean): Array<SdBoneEdge> {
    this.LowestCostToTarget = Number.POSITIVE_INFINITY
    this.ClosestTargetVertex = null
    while (this.Queue.count > 0) {
      const hu = {priority: 0}
      const bestNode: SdVertex = this.Queue.DequeueAndGetPriority(hu)
      if (hu.priority >= this.LowestCostToTarget) {
        continue
      }

      // update the rest
      for (let i = 0; i < bestNode.OutBoneEdges.length; i++) {
        const outBoneEdge = bestNode.OutBoneEdges[i]
        if (outBoneEdge.IsPassable) {
          this.ProcessOutcomingBoneEdge(bestNode, outBoneEdge, pathDirection, lookingForMonotonePath)
        }
      }

      for (let i = 0; i < bestNode.InBoneEdges.length; i++) {
        const inBoneEdge = bestNode.InBoneEdges[i]
        if (inBoneEdge.IsPassable) {
          this.ProcessIncomingBoneEdge(bestNode, inBoneEdge, pathDirection, lookingForMonotonePath)
        }
      }
    }

    return this.GetPathAndUpdateRelatedCosts()
  }

  ProcessOutcomingBoneEdge(v: SdVertex, outBoneEdge: SdBoneEdge, pathDirection: Point, lookingForMonotonePath: boolean) {
    //Assert.assert(v === outBoneEdge.Source)
    if (lookingForMonotonePath && pathDirection.dot(outBoneEdge.TargetPoint.sub(outBoneEdge.SourcePoint)) < 0) {
      return
    }

    this.ProcessBoneEdge(v, outBoneEdge.Target, outBoneEdge)
  }

  ProcessIncomingBoneEdge(v: SdVertex, inBoneEdge: SdBoneEdge, pathDirection: Point, lookingForMonotonePath: boolean) {
    //Assert.assert(v === inBoneEdge.Target)
    if (lookingForMonotonePath && pathDirection.dot(inBoneEdge.SourcePoint.sub(inBoneEdge.TargetPoint)) < 0) {
      return
    }

    this.ProcessBoneEdge(v, inBoneEdge.Source, inBoneEdge)
  }

  ProcessBoneEdge(v: SdVertex, queueCandidate: SdVertex, boneEdge: SdBoneEdge) {
    const newCost: number = this.GetEdgeAdditionalCost(boneEdge, v.Cost)
    if (queueCandidate.Cost <= newCost) {
      return
    }

    queueCandidate.Cost = newCost
    queueCandidate.PrevEdge = boneEdge
    if (this.Queue.ContainsElement(queueCandidate)) {
      this.Queue.DecreasePriority(queueCandidate, newCost)
    } else {
      if (queueCandidate.IsTargetOfRouting) {
        let costToTarget = 0
        if (this.CurrentEdgeGeometry.targetPort instanceof ClusterBoundaryPort) {
          costToTarget = this.LengthCoefficient * queueCandidate.Point.sub(this.CurrentEdgeGeometry.targetPort.Location).length
        }

        if (newCost + costToTarget < this.LowestCostToTarget) {
          this.LowestCostToTarget = newCost + costToTarget
          this.ClosestTargetVertex = queueCandidate
        }

        return
        // do not enqueue the target vertices
      }

      this.Enqueue(queueCandidate)
    }
  }

  GetPathAndUpdateRelatedCosts(): Array<SdBoneEdge> {
    // restore the path by moving backwards
    let current = this.ClosestTargetVertex
    if (current == null) {
      return null
    }

    const result = new Array<SdBoneEdge>()
    while (current.PrevEdge != null) {
      result.push(current.PrevEdge)
      this.RegisterPathInBoneEdge(current.PrevEdge)
      current = current.Prev
    }

    this.EdgesToRouteSources.set(this.CurrentEdgeGeometry, current)
    result.reverse()
    //Assert.assert(result.length > 0)
    return result
  }

  RegisterPathInBoneEdge(boneEdge: SdBoneEdge) {
    boneEdge.AddOccupiedEdge()
    if (this.cdt != null && this.BundlingSettings.CapacityOverflowCoefficient !== 0) {
      this.UpdateResidualCostsOfCrossedCdtEdges(boneEdge)
    }
  }

  UpdateResidualCostsOfCrossedCdtEdges(boneEdge: SdBoneEdge) {
    for (const cdtEdge of boneEdge.CrossedCdtEdges) {
      if (this.AdjacentToSourceOrTarget(cdtEdge)) continue
      if (cdtEdge.ResidualCapacity === cdtEdge.Capacity) {
        cdtEdge.ResidualCapacity -= this.BundlingSettings.edgeWidthShrinkCoeff * this.CurrentEdgeGeometry.lineWidth
      } else {
        cdtEdge.ResidualCapacity -= this.BundlingSettings.ActualEdgeWidth(this.CurrentEdgeGeometry)
      }
    }
  }

  H(v: SdVertex): number {
    return v.Cost + this.LengthCoefficient * v.Point.sub(this.CurrentEdgeGeometry.targetPort.Location).length
  }

  GetEdgeAdditionalCost(boneEdge: SdBoneEdge, previousCost: number): number {
    const len = boneEdge.TargetPoint.sub(boneEdge.SourcePoint).length
    return (
      this.LengthCoefficient * len +
      previousCost +
      (boneEdge.IsOccupied ? 0 : this.BundlingSettings.InkImportance * len) +
      this.CapacityOverflowCost(boneEdge)
    )
  }

  CapacityOverflowCost(boneEdge: SdBoneEdge): number {
    if (this.cdt == null || this.BundlingSettings.CapacityOverflowCoefficient === 0) return 0
    let ret = 0
    for (const cdtEdge of this.CrossedCdtEdgesOfBoneEdge(boneEdge)) {
      ret += this.CostOfCrossingCdtEdgeLocal(
        this.capacityOverlowPenaltyMultiplier,
        this.BundlingSettings,
        this.CurrentEdgeGeometry,
        cdtEdge,
      )
    }
    return ret
  }

  CrossedCdtEdgesOfBoneEdge(boneEdge: SdBoneEdge): Array<CdtEdge> {
    if (boneEdge.CrossedCdtEdges != null) return Array.from(boneEdge.CrossedCdtEdges)
    return Array.from((boneEdge.CrossedCdtEdges = this.ThreadBoneEdgeThroughCdt(boneEdge)))
  }

  ThreadBoneEdgeThroughCdt(boneEdge: SdBoneEdge): Set<CdtEdge> {
    const start = boneEdge.SourcePoint
    const currentTriangle = boneEdge.Source.Triangle
    //Assert.assert(Cdt.PointIsInsideOfTriangle(start, currentTriangle))
    const crossedEdges = new Set<CdtEdge>()
    const end = boneEdge.TargetPoint
    if (Cdt.PointIsInsideOfTriangle(end, currentTriangle)) {
      return crossedEdges
    }

    const threader = new CdtThreader(currentTriangle, start, end)
    while (threader.MoveNext()) {
      const piercedEdge: CdtEdge = threader.CurrentPiercedEdge
      //Assert.assert(piercedEdge != null)
      if (this.Gates.has(piercedEdge)) {
        crossedEdges.add(piercedEdge)
      }
    }

    // if(ddd(boneEdge))
    // CdtSweeper.ShowFront(Cdt.GetTriangles(),null,new []{new LineSegment(boneEdge.SourcePoint,boneEdge.TargetPoint)}, crossedEdges.Select(e=>new LineSegment(e.upperSite.point,e.lowerSite.point)));
    return crossedEdges
  }

  // TODO: method incorrect since id doesn't check AdjacentToSourceOrTarget condition
  static CostOfCrossingCdtEdge(
    capacityOverflMult: number,
    bundlingSettings: BundlingSettings,
    currentEdgeGeometry: GeomEdge,
    e: CdtEdge,
  ): number {
    let w = currentEdgeGeometry.lineWidth * bundlingSettings.edgeWidthShrinkCoeff
    if (e.Capacity !== e.ResidualCapacity) {
      w += bundlingSettings.EdgeSeparation * bundlingSettings.edgeWidthShrinkCoeff
    }

    const del = e.ResidualCapacity - w
    if (del >= 0) {
      return 0
    }

    return -del * capacityOverflMult
  }

  CostOfCrossingCdtEdgeLocal(
    capacityOverflMult: number,
    bundlingSettings: BundlingSettings,
    currentEdgeGeometry: GeomEdge,
    e: CdtEdge,
  ): number {
    if (this.AdjacentToSourceOrTarget(e)) {
      return 0
    }

    return SdShortestPath.CostOfCrossingCdtEdge(capacityOverflMult, bundlingSettings, currentEdgeGeometry, e)
  }

  AdjacentToSourceOrTarget(e: CdtEdge): boolean {
    return (
      e.upperSite.Owner === this.sourceLoosePoly ||
      e.lowerSite.Owner === this.sourceLoosePoly ||
      e.upperSite.Owner === this.targetLoosePoly ||
      e.lowerSite.Owner === this.targetLoosePoly
    )
  }

  SetLengthCoefficient() {
    const idealEdgeLength: number = this.GetIdealDistanceBetweenSourceAndTarget(this.CurrentEdgeGeometry)
    this.LengthCoefficient = this.BundlingSettings.PathLengthImportance / idealEdgeLength
  }

  GetIdealDistanceBetweenSourceAndTarget(geomEdge: GeomEdge): number {
    return geomEdge.sourcePort.Location.sub(geomEdge.targetPort.Location).length
  }

  SetPortVerticesAndObstacles(port: Port, sources: boolean): Polyline {
    let poly: Polyline
    if (port instanceof ClusterBoundaryPort) {
      const cbport = port as ClusterBoundaryPort
      //SplineRouter.ShowVisGraph(this.VisibilityGraph, this.ObstacleHierarchy.GetAllLeaves(), null, new[]{cbport.LoosePolyline});
      poly = cbport.LoosePolyline
      for (const point of poly) {
        let initialCost = 0
        if (sources) {
          //we prefer paths starting from the center of the group
          initialCost = this.LengthCoefficient * point.sub(this.CurrentEdgeGeometry.sourcePort.Location).length
        }
        this.AddAndEnqueueVertexToEnds(point, sources, initialCost)
      }
    } else {
      if (port instanceof HookUpAnywhereFromInsidePort) {
        const anywherePort = port as HookUpAnywhereFromInsidePort
        poly = anywherePort.LoosePolyline
        for (const point of poly) this.AddAndEnqueueVertexToEnds(point, sources, 0)
      } else {
        this.AddAndEnqueueVertexToEnds(port.Location, sources, 0)
        const polys = Array.from(this.ObstacleHierarchy.GetNodeItemsIntersectingRectangle(port.Curve.boundingBox))
        let mindiag = polys[0].boundingBox.diagonal
        poly = polys[0]
        for (let i = 1; i < polys.length; i++) {
          const pl = polys[i]
          const diag = pl.boundingBox.diagonal
          if (diag < mindiag) {
            mindiag = diag
            poly = pl
          }
        }
      }
    }
    return poly
  }

  Enqueue(simpleSdVertex: SdVertex) {
    this.Queue.Enqueue(simpleSdVertex, this.H(simpleSdVertex))
  }

  AddAndEnqueueVertexToEnds(point: Point, isSource: boolean, initialCost: number) {
    const v = this.FindVertex(point)
    const sdVert = this.VisibilityVerticesToSdVerts.get(v)
    if (isSource) {
      sdVert.IsSourceOfRouting = true
      sdVert.Cost = initialCost
      this.Enqueue(sdVert)
    } else {
      sdVert.IsTargetOfRouting = true
    }
  }

  FindVertex(p: Point): VisibilityVertex {
    return this.VisibilityGraph.FindVertex(p) // in the C# version there is a backup search with rounding
  }

  Initialize() {
    this.CreateRoutingGraph()
    if (this.cdt != null) {
      this.capacityOverlowPenaltyMultiplier = SdShortestPath.CapacityOverflowPenaltyMultiplier(this.BundlingSettings)
      this.SetVertexTriangles()
      this.CalculateCapacitiesOfTrianglulation()
    }
  }

  CalculateCapacitiesOfTrianglulation() {
    for (const e of this.Gates) SdShortestPath.CalculateCdtEdgeCapacityForEdge(e)
  }

  static CalculateCdtEdgeCapacityForEdge(e: CdtEdge) {
    if (e.constrained || e.CwTriangle == null || e.CcwTriangle == null) {
      return
    }

    // this is a convex hull edge or an obstacle edge
    const startPoly = <Polyline>e.upperSite.Owner
    const endPoly = <Polyline>e.lowerSite.Owner
    if (startPoly !== endPoly) {
      // e.Capacity = Polygon.Distance(new Polygon(startPoly), new Polygon(endPoly)); //todo: cache this
      // e.Capacity = (e.upperSite.point - e.lowerSite.point).length;
      const distA: number = Polygon.DistancePoint(new Polygon(startPoly), e.lowerSite.point)
      const distB: number = Polygon.DistancePoint(new Polygon(endPoly), e.upperSite.point)
      e.Capacity = (distA + distB) / 2
    }

    // else - it is a diagonal of an obstacle, do not care
  }

  SetVertexTriangles() {
    const triangleTree = CreateRectNodeOnArrayOfRectNodes(
      Array.from(this.cdt.GetTriangles()).map((t) => mkRectangleNode(t, t.BoundingBox())),
    )
    const vertexTree = CreateRectNodeOnArrayOfRectNodes(this.vertexArray.map((v) => mkRectangleNode(v, Rectangle.mkOnPoints([v.Point]))))

    CrossRectangleNodes(triangleTree, vertexTree, (a, b) => this.TryToAssigenTriangleToVertex(a, b))
  }

  TryToAssigenTriangleToVertex(triangle: CdtTriangle, vertex: SdVertex) {
    if (vertex.Triangle != null) {
      return
    }

    if (Cdt.PointIsInsideOfTriangle(vertex.Point, triangle)) {
      vertex.Triangle = triangle
    }
  }

  static CapacityOverflowPenaltyMultiplier(bundlingSettings: BundlingSettings): number {
    return bundlingSettings.CapacityOverflowCoefficient * (bundlingSettings.PathLengthImportance + bundlingSettings.InkImportance)
  }

  // compute cdt edges crossed by paths
  FillCrossedCdtEdges(crossedCdtEdges: Map<GeomEdge, Set<CdtEdge>>) {
    for (const geometryEdge of this.geomEdges) {
      this.sourceLoosePoly = this.SetPortVerticesAndObstacles(geometryEdge.sourcePort, true)
      this.targetLoosePoly = this.SetPortVerticesAndObstacles(geometryEdge.targetPort, false)

      //crossedCdtEdges.Add(geometryEdge, new Set<CdtEdge>());
      for (const boneEdge of this.EdgesToRoutes.get(geometryEdge)) {
        for (const cdtEdge of this.CrossedCdtEdgesOfBoneEdge(boneEdge)) {
          if (this.AdjacentToSourceOrTarget(cdtEdge)) continue
          addToMapOfSets(crossedCdtEdges, geometryEdge, cdtEdge)
        }
      }
    }
  }
}

constructor(makeTransparentShapesOfEdgeGeometryAndGetTheShapes: (e: GeomEdge) => Array<Shape>, cdt: Cdt, gates: Set<CdtEdge>) {
    this.MakeTransparentShapesOfEdgeGeometry = makeTransparentShapesOfEdgeGeometryAndGetTheShapes
    this.cdt = cdt
    this.Gates = gates
  }

CreateGraphElements() {
    for (const sdVertex of this.vertexArray) {
      const vv = sdVertex.VisibilityVertex
      for (const vEdge of vv.InEdges) {
        const boneEdge = new SdBoneEdge(
          vEdge,
          this.VisibilityVerticesToSdVerts.get(vEdge.Source),
          this.VisibilityVerticesToSdVerts.get(vEdge.Target),
        )
        const otherSdVertex = this.VisibilityVerticesToSdVerts.get(vEdge.Source)
        sdVertex.InBoneEdges.push(boneEdge)
        otherSdVertex.OutBoneEdges.push(boneEdge)
      }
    }
  }

CreateRoutingGraph() {
    this.vertexArray = []
    this.VisibilityVerticesToSdVerts = new Map<VisibilityVertex, SdVertex>()
    for (const v of this.VisibilityGraph.Vertices()) {
      const sdVert = new SdVertex(v)
      this.vertexArray.push(sdVert)
      this.VisibilityVerticesToSdVerts.set(v, sdVert)
    }

    this.CreateGraphElements()
  }

RouteEdges() {
    this.Initialize()
    this.RestoreCapacities()
    for (const geomEdge of this.geomEdges) {
      this.EdgesToRoutes.set(geomEdge, this.RouteEdge(geomEdge))
    }

    this.RerouteEdges()

    for (const geomEdge of this.geomEdges) this.SetEdgeGeometryCurve(geomEdge)
  }

SetEdgeGeometryCurve(geomEdge: GeomEdge) {
    const poly = new Polyline()
    let curV = this.EdgesToRouteSources.get(geomEdge)
    poly.addPoint(curV.Point)
    for (const edge of this.EdgesToRoutes.get(geomEdge)) {
      if (edge.SourcePoint.equal(curV.Point)) {
        poly.addPoint(edge.TargetPoint)
        curV = edge.Target
      } else {
        poly.addPoint(edge.SourcePoint)
        curV = edge.Source
      }
    }

    geomEdge.curve = poly
    const isClusterSourcePort = geomEdge.sourcePort instanceof ClusterBoundaryPort
    if (isClusterSourcePort) SdShortestPath.ExtendPolylineStartToClusterBoundary(poly, (<ClusterBoundaryPort>geomEdge.sourcePort).Curve)

    const isClusterTargetPort = geomEdge.targetPort instanceof ClusterBoundaryPort
    if (isClusterTargetPort) SdShortestPath.ExtendPolylineEndToClusterBoundary(poly, (<ClusterBoundaryPort>geomEdge.targetPort).Curve)
  }

static ExtendPolylineEndToClusterBoundary(poly: Polyline, curve: ICurve) {
    const par = curve.closestParameter(poly.end)
    poly.addPoint(curve.value(par))
  }

static ExtendPolylineStartToClusterBoundary(poly: Polyline, curve: ICurve) {
    const par = curve.closestParameter(poly.start)
    poly.PrependPoint(curve.value(par))
  }

RerouteEdges() {
    this.RestoreCapacities()
    for (const geomEdge of this.geomEdges) {
      const newRoute = this.RerouteEdge(geomEdge)
      this.EdgesToRoutes.set(geomEdge, newRoute)
    }
  }

RestoreCapacities() {
    if (this.cdt != null) {
      this.cdt.RestoreEdgeCapacities()
    }
  }

RerouteEdge(geomEdge: GeomEdge): Array<SdBoneEdge> {
    const route = this.EdgesToRoutes.get(geomEdge)

    for (const edge of route) edge.RemoveOccupiedEdge()

    return this.RouteEdge(geomEdge)
  }

RouteEdge(geomEdge: GeomEdge): Array<SdBoneEdge> {
    this.CurrentEdgeGeometry = geomEdge
    for (let i = 0; i < this.vertexArray.length; i++) {
      const sdv = this.vertexArray[i]
      sdv.SetPreviousToNull()
      sdv.IsTargetOfRouting = sdv.IsSourceOfRouting = false
    }

    const transparentShapes = this.MakeTransparentShapesOfEdgeGeometry(geomEdge)
    const ret = this.RouteEdgeWithGroups()
    for (const shape of transparentShapes) shape.IsTransparent = false
    return ret
  }

RouteEdgeWithGroups(): Array<SdBoneEdge> {
    for (let i = 0; i < 2; i++) {
      this.SetLengthCoefficient()
      this.Queue = new GenericBinaryHeapPriorityQueue<SdVertex>()
      this.sourceLoosePoly = this.SetPortVerticesAndObstacles(this.CurrentEdgeGeometry.sourcePort, true)
      this.targetLoosePoly = this.SetPortVerticesAndObstacles(this.CurrentEdgeGeometry.targetPort, false)
      const ret: Array<SdBoneEdge> = this.RouteOnKnownSourceTargetVertices(
        this.CurrentEdgeGeometry.targetPort.Location.sub(this.CurrentEdgeGeometry.sourcePort.Location).normalize(),
        i === 0,
      )
      if (ret != null) {
        return ret
      }

      for (let j = 0; j < this.vertexArray.length; j++) {
        this.vertexArray[j].SetPreviousToNull()
      }
    }

    // SplineRouter.ShowVisGraph('./tmp/badVis.svg', this.VisibilityGraph, Array.from(this.ObstacleHierarchy.GetAllLeaves()), null, [
    //  LineSegment.mkPP(this.CurrentEdgeGeometry.sourcePort.Location, this.CurrentEdgeGeometry.targetPort.Location),
    // ])
    throw new Error()
  }

RouteOnKnownSourceTargetVertices(pathDirection: Point, lookingForMonotonePath: boolean): Array<SdBoneEdge> {
    this.LowestCostToTarget = Number.POSITIVE_INFINITY
    this.ClosestTargetVertex = null
    while (this.Queue.count > 0) {
      const hu = {priority: 0}
      const bestNode: SdVertex = this.Queue.DequeueAndGetPriority(hu)
      if (hu.priority >= this.LowestCostToTarget) {
        continue
      }

      // update the rest
      for (let i = 0; i < bestNode.OutBoneEdges.length; i++) {
        const outBoneEdge = bestNode.OutBoneEdges[i]
        if (outBoneEdge.IsPassable) {
          this.ProcessOutcomingBoneEdge(bestNode, outBoneEdge, pathDirection, lookingForMonotonePath)
        }
      }

      for (let i = 0; i < bestNode.InBoneEdges.length; i++) {
        const inBoneEdge = bestNode.InBoneEdges[i]
        if (inBoneEdge.IsPassable) {
          this.ProcessIncomingBoneEdge(bestNode, inBoneEdge, pathDirection, lookingForMonotonePath)
        }
      }
    }

    return this.GetPathAndUpdateRelatedCosts()
  }

ProcessOutcomingBoneEdge(v: SdVertex, outBoneEdge: SdBoneEdge, pathDirection: Point, lookingForMonotonePath: boolean) {
    //Assert.assert(v === outBoneEdge.Source)
    if (lookingForMonotonePath && pathDirection.dot(outBoneEdge.TargetPoint.sub(outBoneEdge.SourcePoint)) < 0) {
      return
    }

    this.ProcessBoneEdge(v, outBoneEdge.Target, outBoneEdge)
  }

ProcessIncomingBoneEdge(v: SdVertex, inBoneEdge: SdBoneEdge, pathDirection: Point, lookingForMonotonePath: boolean) {
    //Assert.assert(v === inBoneEdge.Target)
    if (lookingForMonotonePath && pathDirection.dot(inBoneEdge.SourcePoint.sub(inBoneEdge.TargetPoint)) < 0) {
      return
    }

    this.ProcessBoneEdge(v, inBoneEdge.Source, inBoneEdge)
  }

ProcessBoneEdge(v: SdVertex, queueCandidate: SdVertex, boneEdge: SdBoneEdge) {
    const newCost: number = this.GetEdgeAdditionalCost(boneEdge, v.Cost)
    if (queueCandidate.Cost <= newCost) {
      return
    }

    queueCandidate.Cost = newCost
    queueCandidate.PrevEdge = boneEdge
    if (this.Queue.ContainsElement(queueCandidate)) {
      this.Queue.DecreasePriority(queueCandidate, newCost)
    } else {
      if (queueCandidate.IsTargetOfRouting) {
        let costToTarget = 0
        if (this.CurrentEdgeGeometry.targetPort instanceof ClusterBoundaryPort) {
          costToTarget = this.LengthCoefficient * queueCandidate.Point.sub(this.CurrentEdgeGeometry.targetPort.Location).length
        }

        if (newCost + costToTarget < this.LowestCostToTarget) {
          this.LowestCostToTarget = newCost + costToTarget
          this.ClosestTargetVertex = queueCandidate
        }

        return
        // do not enqueue the target vertices
      }

      this.Enqueue(queueCandidate)
    }
  }

GetPathAndUpdateRelatedCosts(): Array<SdBoneEdge> {
    // restore the path by moving backwards
    let current = this.ClosestTargetVertex
    if (current == null) {
      return null
    }

    const result = new Array<SdBoneEdge>()
    while (current.PrevEdge != null) {
      result.push(current.PrevEdge)
      this.RegisterPathInBoneEdge(current.PrevEdge)
      current = current.Prev
    }

    this.EdgesToRouteSources.set(this.CurrentEdgeGeometry, current)
    result.reverse()
    //Assert.assert(result.length > 0)
    return result
  }

RegisterPathInBoneEdge(boneEdge: SdBoneEdge) {
    boneEdge.AddOccupiedEdge()
    if (this.cdt != null && this.BundlingSettings.CapacityOverflowCoefficient !== 0) {
      this.UpdateResidualCostsOfCrossedCdtEdges(boneEdge)
    }
  }

UpdateResidualCostsOfCrossedCdtEdges(boneEdge: SdBoneEdge) {
    for (const cdtEdge of boneEdge.CrossedCdtEdges) {
      if (this.AdjacentToSourceOrTarget(cdtEdge)) continue
      if (cdtEdge.ResidualCapacity === cdtEdge.Capacity) {
        cdtEdge.ResidualCapacity -= this.BundlingSettings.edgeWidthShrinkCoeff * this.CurrentEdgeGeometry.lineWidth
      } else {
        cdtEdge.ResidualCapacity -= this.BundlingSettings.ActualEdgeWidth(this.CurrentEdgeGeometry)
      }
    }
  }

H(v: SdVertex): number {
    return v.Cost + this.LengthCoefficient * v.Point.sub(this.CurrentEdgeGeometry.targetPort.Location).length
  }

GetEdgeAdditionalCost(boneEdge: SdBoneEdge, previousCost: number): number {
    const len = boneEdge.TargetPoint.sub(boneEdge.SourcePoint).length
    return (
      this.LengthCoefficient * len +
      previousCost +
      (boneEdge.IsOccupied ? 0 : this.BundlingSettings.InkImportance * len) +
      this.CapacityOverflowCost(boneEdge)
    )
  }

CapacityOverflowCost(boneEdge: SdBoneEdge): number {
    if (this.cdt == null || this.BundlingSettings.CapacityOverflowCoefficient === 0) return 0
    let ret = 0
    for (const cdtEdge of this.CrossedCdtEdgesOfBoneEdge(boneEdge)) {
      ret += this.CostOfCrossingCdtEdgeLocal(
        this.capacityOverlowPenaltyMultiplier,
        this.BundlingSettings,
        this.CurrentEdgeGeometry,
        cdtEdge,
      )
    }
    return ret
  }

CrossedCdtEdgesOfBoneEdge(boneEdge: SdBoneEdge): Array<CdtEdge> {
    if (boneEdge.CrossedCdtEdges != null) return Array.from(boneEdge.CrossedCdtEdges)
    return Array.from((boneEdge.CrossedCdtEdges = this.ThreadBoneEdgeThroughCdt(boneEdge)))
  }

ThreadBoneEdgeThroughCdt(boneEdge: SdBoneEdge): Set<CdtEdge> {
    const start = boneEdge.SourcePoint
    const currentTriangle = boneEdge.Source.Triangle
    //Assert.assert(Cdt.PointIsInsideOfTriangle(start, currentTriangle))
    const crossedEdges = new Set<CdtEdge>()
    const end = boneEdge.TargetPoint
    if (Cdt.PointIsInsideOfTriangle(end, currentTriangle)) {
      return crossedEdges
    }

    const threader = new CdtThreader(currentTriangle, start, end)
    while (threader.MoveNext()) {
      const piercedEdge: CdtEdge = threader.CurrentPiercedEdge
      //Assert.assert(piercedEdge != null)
      if (this.Gates.has(piercedEdge)) {
        crossedEdges.add(piercedEdge)
      }
    }

    // if(ddd(boneEdge))
    // CdtSweeper.ShowFront(Cdt.GetTriangles(),null,new []{new LineSegment(boneEdge.SourcePoint,boneEdge.TargetPoint)}, crossedEdges.Select(e=>new LineSegment(e.upperSite.point,e.lowerSite.point)));
    return crossedEdges
  }

static CostOfCrossingCdtEdge(
    capacityOverflMult: number,
    bundlingSettings: BundlingSettings,
    currentEdgeGeometry: GeomEdge,
    e: CdtEdge,
  ): number {
    let w = currentEdgeGeometry.lineWidth * bundlingSettings.edgeWidthShrinkCoeff
    if (e.Capacity !== e.ResidualCapacity) {
      w += bundlingSettings.EdgeSeparation * bundlingSettings.edgeWidthShrinkCoeff
    }

    const del = e.ResidualCapacity - w
    if (del >= 0) {
      return 0
    }

    return -del * capacityOverflMult
  }

CostOfCrossingCdtEdgeLocal(
    capacityOverflMult: number,
    bundlingSettings: BundlingSettings,
    currentEdgeGeometry: GeomEdge,
    e: CdtEdge,
  ): number {
    if (this.AdjacentToSourceOrTarget(e)) {
      return 0
    }

    return SdShortestPath.CostOfCrossingCdtEdge(capacityOverflMult, bundlingSettings, currentEdgeGeometry, e)
  }

AdjacentToSourceOrTarget(e: CdtEdge): boolean {
    return (
      e.upperSite.Owner === this.sourceLoosePoly ||
      e.lowerSite.Owner === this.sourceLoosePoly ||
      e.upperSite.Owner === this.targetLoosePoly ||
      e.lowerSite.Owner === this.targetLoosePoly
    )
  }

SetLengthCoefficient() {
    const idealEdgeLength: number = this.GetIdealDistanceBetweenSourceAndTarget(this.CurrentEdgeGeometry)
    this.LengthCoefficient = this.BundlingSettings.PathLengthImportance / idealEdgeLength
  }

GetIdealDistanceBetweenSourceAndTarget(geomEdge: GeomEdge): number {
    return geomEdge.sourcePort.Location.sub(geomEdge.targetPort.Location).length
  }

SetPortVerticesAndObstacles(port: Port, sources: boolean): Polyline {
    let poly: Polyline
    if (port instanceof ClusterBoundaryPort) {
      const cbport = port as ClusterBoundaryPort
      //SplineRouter.ShowVisGraph(this.VisibilityGraph, this.ObstacleHierarchy.GetAllLeaves(), null, new[]{cbport.LoosePolyline});
      poly = cbport.LoosePolyline
      for (const point of poly) {
        let initialCost = 0
        if (sources) {
          //we prefer paths starting from the center of the group
          initialCost = this.LengthCoefficient * point.sub(this.CurrentEdgeGeometry.sourcePort.Location).length
        }
        this.AddAndEnqueueVertexToEnds(point, sources, initialCost)
      }
    } else {
      if (port instanceof HookUpAnywhereFromInsidePort) {
        const anywherePort = port as HookUpAnywhereFromInsidePort
        poly = anywherePort.LoosePolyline
        for (const point of poly) this.AddAndEnqueueVertexToEnds(point, sources, 0)
      } else {
        this.AddAndEnqueueVertexToEnds(port.Location, sources, 0)
        const polys = Array.from(this.ObstacleHierarchy.GetNodeItemsIntersectingRectangle(port.Curve.boundingBox))
        let mindiag = polys[0].boundingBox.diagonal
        poly = polys[0]
        for (let i = 1; i < polys.length; i++) {
          const pl = polys[i]
          const diag = pl.boundingBox.diagonal
          if (diag < mindiag) {
            mindiag = diag
            poly = pl
          }
        }
      }
    }
    return poly
  }

Enqueue(simpleSdVertex: SdVertex) {
    this.Queue.Enqueue(simpleSdVertex, this.H(simpleSdVertex))
  }

AddAndEnqueueVertexToEnds(point: Point, isSource: boolean, initialCost: number) {
    const v = this.FindVertex(point)
    const sdVert = this.VisibilityVerticesToSdVerts.get(v)
    if (isSource) {
      sdVert.IsSourceOfRouting = true
      sdVert.Cost = initialCost
      this.Enqueue(sdVert)
    } else {
      sdVert.IsTargetOfRouting = true
    }
  }

FindVertex(p: Point): VisibilityVertex {
    return this.VisibilityGraph.FindVertex(p) // in the C# version there is a backup search with rounding
  }

Initialize() {
    this.CreateRoutingGraph()
    if (this.cdt != null) {
      this.capacityOverlowPenaltyMultiplier = SdShortestPath.CapacityOverflowPenaltyMultiplier(this.BundlingSettings)
      this.SetVertexTriangles()
      this.CalculateCapacitiesOfTrianglulation()
    }
  }

CalculateCapacitiesOfTrianglulation() {
    for (const e of this.Gates) SdShortestPath.CalculateCdtEdgeCapacityForEdge(e)
  }

static CalculateCdtEdgeCapacityForEdge(e: CdtEdge) {
    if (e.constrained || e.CwTriangle == null || e.CcwTriangle == null) {
      return
    }

    // this is a convex hull edge or an obstacle edge
    const startPoly = <Polyline>e.upperSite.Owner
    const endPoly = <Polyline>e.lowerSite.Owner
    if (startPoly !== endPoly) {
      // e.Capacity = Polygon.Distance(new Polygon(startPoly), new Polygon(endPoly)); //todo: cache this
      // e.Capacity = (e.upperSite.point - e.lowerSite.point).length;
      const distA: number = Polygon.DistancePoint(new Polygon(startPoly), e.lowerSite.point)
      const distB: number = Polygon.DistancePoint(new Polygon(endPoly), e.upperSite.point)
      e.Capacity = (distA + distB) / 2
    }

    // else - it is a diagonal of an obstacle, do not care
  }

SetVertexTriangles() {
    const triangleTree = CreateRectNodeOnArrayOfRectNodes(
      Array.from(this.cdt.GetTriangles()).map((t) => mkRectangleNode(t, t.BoundingBox())),
    )
    const vertexTree = CreateRectNodeOnArrayOfRectNodes(this.vertexArray.map((v) => mkRectangleNode(v, Rectangle.mkOnPoints([v.Point]))))

    CrossRectangleNodes(triangleTree, vertexTree, (a, b) => this.TryToAssigenTriangleToVertex(a, b))
  }

TryToAssigenTriangleToVertex(triangle: CdtTriangle, vertex: SdVertex) {
    if (vertex.Triangle != null) {
      return
    }

    if (Cdt.PointIsInsideOfTriangle(vertex.Point, triangle)) {
      vertex.Triangle = triangle
    }
  }

static CapacityOverflowPenaltyMultiplier(bundlingSettings: BundlingSettings): number {
    return bundlingSettings.CapacityOverflowCoefficient * (bundlingSettings.PathLengthImportance + bundlingSettings.InkImportance)
  }

FillCrossedCdtEdges(crossedCdtEdges: Map<GeomEdge, Set<CdtEdge>>) {
    for (const geometryEdge of this.geomEdges) {
      this.sourceLoosePoly = this.SetPortVerticesAndObstacles(geometryEdge.sourcePort, true)
      this.targetLoosePoly = this.SetPortVerticesAndObstacles(geometryEdge.targetPort, false)

      //crossedCdtEdges.Add(geometryEdge, new Set<CdtEdge>());
      for (const boneEdge of this.EdgesToRoutes.get(geometryEdge)) {
        for (const cdtEdge of this.CrossedCdtEdgesOfBoneEdge(boneEdge)) {
          if (this.AdjacentToSourceOrTarget(cdtEdge)) continue
          addToMapOfSets(crossedCdtEdges, geometryEdge, cdtEdge)
        }
      }
    }
  }

export class SdVertex {
  VisibilityVertex: VisibilityVertex

  InBoneEdges: Array<SdBoneEdge> = new Array<SdBoneEdge>()

  OutBoneEdges: Array<SdBoneEdge> = new Array<SdBoneEdge>()

  get Prev(): SdVertex {
    if (this.PrevEdge == null) {
      return null
    }
    return this.PrevEdge.Source === this ? this.PrevEdge.Target : this.PrevEdge.Source
  }

  PrevEdge: SdBoneEdge

  constructor(visibilityVertex: VisibilityVertex) {
    this.VisibilityVertex = visibilityVertex
  }

  Triangle: CdtTriangle

  IsSourceOfRouting: boolean
  IsTargetOfRouting: boolean

  get Point(): Point {
    return this.VisibilityVertex.point
  }

  cost: number

  get Cost(): number {
    if (this.IsSourceOfRouting) {
      return this.cost
    }
    return this.Prev == null ? Number.POSITIVE_INFINITY : this.cost
  }
  set Cost(value: number) {
    this.cost = value
  }

  public SetPreviousToNull() {
    this.PrevEdge = null
  }
}

constructor(visibilityVertex: VisibilityVertex) {
    this.VisibilityVertex = visibilityVertex
  }

public SetPreviousToNull() {
    this.PrevEdge = null
  }

export class SimulatedAnnealing {
  // bundle data

  metroGraphData: MetroGraphData

  // Algorithm settings

  bundlingSettings: BundlingSettings

  //  calculates rouing cost
  costCalculator: CostCalculator

  //  used for fast calculation of intersections
  cache: IntersectionCache

  // fix routing by simulated annealing algorithm

  static FixRouting(metroGraphData: MetroGraphData, bundlingSettings: BundlingSettings): boolean {
    return this.FixRoutingMBP(metroGraphData, bundlingSettings, null)
  }

  static FixRoutingMBP(metroGraphData: MetroGraphData, bundlingSettings: BundlingSettings, changedPoints: PointSet): boolean {
    return new SimulatedAnnealing(metroGraphData, bundlingSettings).FixRoutingP(changedPoints)
  }

  constructor(metroGraphData: MetroGraphData, bundlingSettings: BundlingSettings) {
    this.metroGraphData = metroGraphData
    this.bundlingSettings = bundlingSettings
    this.costCalculator = new CostCalculator(this.metroGraphData, this.bundlingSettings)
    this.cache = new IntersectionCache(this.metroGraphData, this.bundlingSettings, this.costCalculator, this.metroGraphData.cdt)
  }

  static MaxIterations = 100

  static MaxStep = 50

  static MinStep = 1

  static MinRelativeChange = 0.0005

  stationsForOptimizations: Set<Station>

  // Use constraint edge routing to reduce ink

  FixRoutingP(changedPoints: PointSet): boolean {
    //Assert.assert(SimulatedAnnealing.stationsArePositionedCorrectly(this.metroGraphData))

    this.stationsForOptimizations = this.GetStationsForOptimizations(changedPoints)
    this.cache.InitializeCostCache()
    let step: number = SimulatedAnnealing.MaxStep
    let energy: number = Number.POSITIVE_INFINITY
    let x: Array<Point> = this.metroGraphData.VirtualStations().map((v) => v.Position)
    let iteration = 0
    while (iteration++ < SimulatedAnnealing.MaxIterations) {
      const coordinatesChanged = this.TryMoveStations()
      //TimeMeasurer.DebugOutput("  #iter = " + iteration + " moved: " + cnt + "/" + metroGraphData.VirtualNodes().Count() + " step: " + step);

      if (iteration <= 1 && !coordinatesChanged) return false
      if (!coordinatesChanged) break

      const oldEnergy = energy
      energy = CostCalculator.Cost(this.metroGraphData, this.bundlingSettings)
      //TimeMeasurer.DebugOutput("energy: " + energy);

      step = this.UpdateMaxStep(step, oldEnergy, energy)
      const oldX: Array<Point> = x
      x = this.metroGraphData.VirtualStations().map((v) => v.Position)
      if (step < SimulatedAnnealing.MinStep || this.Converged(step, oldX, x)) {
        break
      }
    }

    // TimeMeasurer.DebugOutput("SA completed after " + iteration + " iterations");
    return true
  }

  static stationsArePositionedCorrectly(metroGraphData: MetroGraphData): boolean {
    for (const e of metroGraphData.VirtualEdges()) {
      if (!this.edgeIsPositionedCorrectly(e, metroGraphData)) return false
    }
    return true
  }

  static edgeIsPositionedCorrectly(e: [Station, Station], metroGraphData: MetroGraphData): boolean {
    const u = e[0]
    const v = e[1]
    const allowedToIntersect = metroGraphData.looseIntersections.ObstaclesToIgnoreForBundle(u, v)

    const ls = LineSegment.mkPP(u.Position, v.Position)
    const intersected = Array.from(metroGraphData.looseIntersections.obstacleTree.GetNodeItemsIntersectingRectangle(ls.boundingBox))
      .filter((poly) => !allowedToIntersect.has(poly))
      .filter((poly) => Curve.CurvesIntersect(ls, poly))
    if (intersected.length > 0) {
      EdgeNudger.ShowHubs(
        metroGraphData,
        null,
        null,
        './tmp/badcross.svg',
        [
          DebugCurve.mkDebugCurveTWCI(200, 1, 'Brown', ls),
          DebugCurve.mkDebugCurveTWCI(200, 1, 'Red', CurveFactory.mkCircle(2, u.Position)),
          DebugCurve.mkDebugCurveTWCI(200, 1, 'Blue', CurveFactory.mkCircle(5, v.Position)),
          DebugCurve.mkDebugCurveTWCI(100, 1, 'Blue', CurveFactory.mkCircle(5, v.Position)),
        ].concat(intersected.map((p) => DebugCurve.mkDebugCurveTWCI(100, 1, 'Pink', p))),
      )
      return false
    } else {
      return true
    }
  }

  GetStationsForOptimizations(changedPoints: PointSet): Set<Station> {
    if (changedPoints == null) {
      return new Set<Station>(this.metroGraphData.VirtualStations())
    } else {
      const result: Set<Station> = new Set<Station>()
      for (const p of changedPoints) {
        const s = this.metroGraphData.PointToStations.get(p)
        if (s && !s.IsReal) result.add(s)
      }
      return result
    }
  }

  // stop SA if relative changes are small

  Converged(step: number, oldx: Array<Point>, newx: Array<Point>): boolean {
    // return false;
    let den = 0
    let num = 0
    for (let i = 0; i < oldx.length; i++) {
      num += oldx[i].sub(newx[i]).lengthSquared
      den += oldx[i].lengthSquared
    }

    const res: number = Math.sqrt(num / den)
    return res < SimulatedAnnealing.MinRelativeChange
  }

  stepsWithProgress = 0

  UpdateMaxStep(step: number, oldEnergy: number, newEnergy: number): number {
    // cooling factor
    const T = 0.8
    if (newEnergy + 1 < oldEnergy) {
      this.stepsWithProgress++
      if (this.stepsWithProgress >= 5) {
        this.stepsWithProgress = 0
        step = Math.min(SimulatedAnnealing.MaxStep, step / T)
      }
    } else {
      this.stepsWithProgress = 0
      step *= T
    }

    return step
  }

  TryMoveStations(): boolean {
    let coordinatesChanged = false
    const movedStations: Set<Station> = new Set<Station>()
    // for (var node of metroGraphData.VirtualNodes()) {
    for (const node of this.stationsForOptimizations) {
      if (this.TryMoveStation(node)) {
        //Assert.assert(this.stationsForOptimizations.has(node))
        coordinatesChanged = true
        movedStations.add(node)
        for (const adj of node.Neighbors) {
          if (!adj.IsReal) {
            movedStations.add(adj)
          }
        }
      }
    }
    this.stationsForOptimizations = movedStations
    return coordinatesChanged
  }

  /** 
    Move node to decrease the cost of the drawing
   Returns true iff position has changed
*/
  TryMoveStation(s: Station): boolean {
    let direction: Point = this.BuildDirection(s)
    if (direction.length === 0) {
      return false
    }

    let stepLength: number = this.BuildStepLength(s, direction)
    if (stepLength < SimulatedAnnealing.MinStep) {
      // try random direction
      direction = RandomPoint()
      stepLength = this.BuildStepLength(s, direction)
      if (stepLength < SimulatedAnnealing.MinStep) {
        return false
      }
    }

    const step: Point = direction.mul(stepLength)
    const newPosition: Point = s.Position.add(step)
    // can this happen?
    if (this.metroGraphData.PointToStations.has(newPosition)) {
      return false
    }

    if (!this.moveIsLegalForAdjacentBundles(s, newPosition)) {
      return false
    }

    this.metroGraphData.MoveNode(s, newPosition)

    this.cache.UpdateCostCache(s)
    return true
  }
  /** checking the node position and neigborhood bundles */
  moveIsLegalForAdjacentBundles(s: Station, sNewPosition: Point): boolean {
    for (const poly of this.metroGraphData.looseIntersections.obstacleTree.AllHitItems(
      Rectangle.mkOnPoints([sNewPosition]),
      (poly) => Curve.PointRelativeToCurveLocation(sNewPosition, poly) !== PointLocation.Outside,
    )) {
      if (s.getELP().has(poly) === false) {
        return false
      }
    }
    for (const t of s.Neighbors) {
      const obstaclesToIgnore = this.metroGraphData.looseIntersections.ObstaclesToIgnoreForBundle(t, s)
      if (!this.metroGraphData.cdtIntersections.EdgeIsLegal_(t.Position, sNewPosition, t.cdtTriangle, obstaclesToIgnore)) return false
    }
    return true
  }

  // Calculate the direction to improve the ink function

  BuildDirection(node: Station): Point {
    const forceInk = this.BuildForceForInk(node)
    const forcePL = this.BuildForceForPathLengths(node)
    const forceR = this.BuildForceForRadius(node)
    const forceBundle = this.BuildForceForBundle(node)
    const force = forceInk.add(forcePL.add(forceR.add(forceBundle)))
    if (force.length < 0.1) {
      return new Point(0, 0)
    }

    return force.normalize()
  }

  BuildStepLength(node: Station, direction: Point): number {
    let stepLength: number = SimulatedAnnealing.MinStep
    let costGain: number = this.CostGain(node, node.Position.add(direction.mul(stepLength)))
    if (costGain < 0.01) {
      return 0
    }

    while (2 * stepLength <= SimulatedAnnealing.MaxStep) {
      const newCostGain: number = this.CostGain(node, node.Position.add(direction.mul(stepLength * 2)))
      if (newCostGain <= costGain) {
        break
      }

      stepLength *= 2
      costGain = newCostGain
    }

    return stepLength
  }

  // Computes cost delta when moving the node
  // the cost will be negative if a new position overlaps obstacles

  CostGain(node: Station, newPosition: Point): number {
    const MInf = -12345678
    const rGain: number = this.costCalculator.RadiusGain(node, newPosition)
    if (rGain < MInf) {
      return MInf
    }

    const bundleGain: number = this.costCalculator.BundleGain(node, newPosition)
    if (bundleGain < MInf) {
      return MInf
    }

    const inkGain: number = this.costCalculator.InkGain(node, newPosition)
    const plGain: number = this.costCalculator.PathLengthsGain(node, newPosition)
    return rGain + inkGain + plGain + bundleGain
  }

  // force to decrease ink

  BuildForceForInk(node: Station): Point {
    //return new Point(0,0);
    let direction = new Point(0, 0)
    for (const adj of node.Neighbors) {
      const p = adj.Position.sub(node.Position)
      direction = direction.add(p.normalize())
    }

    //derivative
    const force = direction.mul(this.bundlingSettings.InkImportance)
    return force
  }

  // direction to decrease path lengths

  BuildForceForPathLengths(node: Station): Point {
    // return new Point(0,0);
    let direction = new Point(0, 0)
    for (const mni of this.metroGraphData.MetroNodeInfosOfNode(node)) {
      const metroline = mni.Metroline
      const u: Point = mni.PolyPoint.next.point
      const v: Point = mni.PolyPoint.prev.point
      const p1 = u.sub(node.Position)
      const p2 = v.sub(node.Position)
      direction = direction.add(p1.div(p1.length * metroline.IdealLength))
      direction = direction.add(p2.div(p2.length * metroline.IdealLength))
    }
    // derivative
    const force: Point = direction.mul(this.bundlingSettings.PathLengthImportance)
    return force
  }

  // direction to increase radii

  BuildForceForRadius(node: Station): Point {
    let direction: Point = new Point(0, 0)
    const idealR: number = node.cachedIdealRadius
    const t: {touchedObstacles: Array<[Polyline, Point]>} = {touchedObstacles: []}
    const res: boolean = this.metroGraphData.looseIntersections.HubAvoidsObstaclesSPNBA(node, node.Position, idealR, t)
    if (!res) {
      EdgeNudger.ShowHubs(this.metroGraphData, null, node, './tmp/hubs.svg', [
        DebugCurve.mkDebugCurveTWCI(255, 1, 'Brown', Intersections.containingPoly),
        DebugCurve.mkDebugCurveTWCI(100, 1, 'Blue', CurveFactory.mkCircle(idealR, node.Position)),
      ])
      throw new Error()
    }
    // throw new Error()
    //Assert.assert(res) // problem here
    for (const d of t.touchedObstacles) {
      const dist: number = d[1].sub(node.Position).length
      //Assert.assert(dist <= idealR)
      const lforce: number = 2 * (1 - dist / idealR)
      const dir: Point = node.Position.sub(d[1]).normalize()
      direction = direction.add(dir.mul(lforce))
    }
    // derivative
    const force: Point = direction.mul(this.bundlingSettings.HubRepulsionImportance)
    return force
  }
  /** calculates the direction to push a bundle away from obstacle*/
  BuildForceForBundle(station: Station): Point {
    let direction = new Point(0, 0)
    for (const adjStation of station.Neighbors) {
      const idealWidth = this.metroGraphData.GetWidthSSN(station, adjStation, this.bundlingSettings.EdgeSeparation)
      const t: {closestDist: Array<[Point, Point]>} = {closestDist: []}
      const res = this.metroGraphData.cdtIntersections.BundleAvoidsObstacles(
        station,
        adjStation,
        station.Position,
        adjStation.Position,
        idealWidth / 2,
        t,
      )
      if (!res && false) {
        EdgeNudger.ShowHubs(this.metroGraphData, null, station, './tmp/inside_forbid.svg', [
          DebugCurve.mkDebugCurveTWCI(100, 0.2, 'Blue', LineSegment.mkPP(station.Position, adjStation.Position)),
          DebugCurve.mkDebugCurveTWCI(100, 0.2, 'Red', CurveFactory.mkCircle(2, station.Position)),
          DebugCurve.mkDebugCurveTWCI(100, 0.2, 'Red', CurveFactory.mkCircle(3, adjStation.Position)),
        ])
      }
      //Assert.assert(res) //todo : still unsolved

      for (const d of t.closestDist) {
        const dist = d[0].sub(d[1]).length
        // Debug.//Assert(LessOrEqual(dist, idealWidth / 2));
        const lforce = 2.0 * (1.0 - dist / (idealWidth / 2))
        const dir = d[0].sub(d[1]).normalize().neg()
        direction = direction.add(dir.mul(lforce))
      }
    }

    //derivative
    const force = direction.mul(this.bundlingSettings.BundleRepulsionImportance)

    return force
  }
}

constructor(metroGraphData: MetroGraphData, bundlingSettings: BundlingSettings) {
    this.metroGraphData = metroGraphData
    this.bundlingSettings = bundlingSettings
    this.costCalculator = new CostCalculator(this.metroGraphData, this.bundlingSettings)
    this.cache = new IntersectionCache(this.metroGraphData, this.bundlingSettings, this.costCalculator, this.metroGraphData.cdt)
  }

static FixRouting(metroGraphData: MetroGraphData, bundlingSettings: BundlingSettings): boolean {
    return this.FixRoutingMBP(metroGraphData, bundlingSettings, null)
  }

static FixRoutingMBP(metroGraphData: MetroGraphData, bundlingSettings: BundlingSettings, changedPoints: PointSet): boolean {
    return new SimulatedAnnealing(metroGraphData, bundlingSettings).FixRoutingP(changedPoints)
  }

FixRoutingP(changedPoints: PointSet): boolean {
    //Assert.assert(SimulatedAnnealing.stationsArePositionedCorrectly(this.metroGraphData))

    this.stationsForOptimizations = this.GetStationsForOptimizations(changedPoints)
    this.cache.InitializeCostCache()
    let step: number = SimulatedAnnealing.MaxStep
    let energy: number = Number.POSITIVE_INFINITY
    let x: Array<Point> = this.metroGraphData.VirtualStations().map((v) => v.Position)
    let iteration = 0
    while (iteration++ < SimulatedAnnealing.MaxIterations) {
      const coordinatesChanged = this.TryMoveStations()
      //TimeMeasurer.DebugOutput("  #iter = " + iteration + " moved: " + cnt + "/" + metroGraphData.VirtualNodes().Count() + " step: " + step);

      if (iteration <= 1 && !coordinatesChanged) return false
      if (!coordinatesChanged) break

      const oldEnergy = energy
      energy = CostCalculator.Cost(this.metroGraphData, this.bundlingSettings)
      //TimeMeasurer.DebugOutput("energy: " + energy);

      step = this.UpdateMaxStep(step, oldEnergy, energy)
      const oldX: Array<Point> = x
      x = this.metroGraphData.VirtualStations().map((v) => v.Position)
      if (step < SimulatedAnnealing.MinStep || this.Converged(step, oldX, x)) {
        break
      }
    }

    // TimeMeasurer.DebugOutput("SA completed after " + iteration + " iterations");
    return true
  }

static stationsArePositionedCorrectly(metroGraphData: MetroGraphData): boolean {
    for (const e of metroGraphData.VirtualEdges()) {
      if (!this.edgeIsPositionedCorrectly(e, metroGraphData)) return false
    }
    return true
  }

static edgeIsPositionedCorrectly(e: [Station, Station], metroGraphData: MetroGraphData): boolean {
    const u = e[0]
    const v = e[1]
    const allowedToIntersect = metroGraphData.looseIntersections.ObstaclesToIgnoreForBundle(u, v)

    const ls = LineSegment.mkPP(u.Position, v.Position)
    const intersected = Array.from(metroGraphData.looseIntersections.obstacleTree.GetNodeItemsIntersectingRectangle(ls.boundingBox))
      .filter((poly) => !allowedToIntersect.has(poly))
      .filter((poly) => Curve.CurvesIntersect(ls, poly))
    if (intersected.length > 0) {
      EdgeNudger.ShowHubs(
        metroGraphData,
        null,
        null,
        './tmp/badcross.svg',
        [
          DebugCurve.mkDebugCurveTWCI(200, 1, 'Brown', ls),
          DebugCurve.mkDebugCurveTWCI(200, 1, 'Red', CurveFactory.mkCircle(2, u.Position)),
          DebugCurve.mkDebugCurveTWCI(200, 1, 'Blue', CurveFactory.mkCircle(5, v.Position)),
          DebugCurve.mkDebugCurveTWCI(100, 1, 'Blue', CurveFactory.mkCircle(5, v.Position)),
        ].concat(intersected.map((p) => DebugCurve.mkDebugCurveTWCI(100, 1, 'Pink', p))),
      )
      return false
    } else {
      return true
    }
  }

GetStationsForOptimizations(changedPoints: PointSet): Set<Station> {
    if (changedPoints == null) {
      return new Set<Station>(this.metroGraphData.VirtualStations())
    } else {
      const result: Set<Station> = new Set<Station>()
      for (const p of changedPoints) {
        const s = this.metroGraphData.PointToStations.get(p)
        if (s && !s.IsReal) result.add(s)
      }
      return result
    }
  }

Converged(step: number, oldx: Array<Point>, newx: Array<Point>): boolean {
    // return false;
    let den = 0
    let num = 0
    for (let i = 0; i < oldx.length; i++) {
      num += oldx[i].sub(newx[i]).lengthSquared
      den += oldx[i].lengthSquared
    }

    const res: number = Math.sqrt(num / den)
    return res < SimulatedAnnealing.MinRelativeChange
  }

UpdateMaxStep(step: number, oldEnergy: number, newEnergy: number): number {
    // cooling factor
    const T = 0.8
    if (newEnergy + 1 < oldEnergy) {
      this.stepsWithProgress++
      if (this.stepsWithProgress >= 5) {
        this.stepsWithProgress = 0
        step = Math.min(SimulatedAnnealing.MaxStep, step / T)
      }
    } else {
      this.stepsWithProgress = 0
      step *= T
    }

    return step
  }

TryMoveStations(): boolean {
    let coordinatesChanged = false
    const movedStations: Set<Station> = new Set<Station>()
    // for (var node of metroGraphData.VirtualNodes()) {
    for (const node of this.stationsForOptimizations) {
      if (this.TryMoveStation(node)) {
        //Assert.assert(this.stationsForOptimizations.has(node))
        coordinatesChanged = true
        movedStations.add(node)
        for (const adj of node.Neighbors) {
          if (!adj.IsReal) {
            movedStations.add(adj)
          }
        }
      }
    }
    this.stationsForOptimizations = movedStations
    return coordinatesChanged
  }

TryMoveStation(s: Station): boolean {
    let direction: Point = this.BuildDirection(s)
    if (direction.length === 0) {
      return false
    }

    let stepLength: number = this.BuildStepLength(s, direction)
    if (stepLength < SimulatedAnnealing.MinStep) {
      // try random direction
      direction = RandomPoint()
      stepLength = this.BuildStepLength(s, direction)
      if (stepLength < SimulatedAnnealing.MinStep) {
        return false
      }
    }

    const step: Point = direction.mul(stepLength)
    const newPosition: Point = s.Position.add(step)
    // can this happen?
    if (this.metroGraphData.PointToStations.has(newPosition)) {
      return false
    }

    if (!this.moveIsLegalForAdjacentBundles(s, newPosition)) {
      return false
    }

    this.metroGraphData.MoveNode(s, newPosition)

    this.cache.UpdateCostCache(s)
    return true
  }

moveIsLegalForAdjacentBundles(s: Station, sNewPosition: Point): boolean {
    for (const poly of this.metroGraphData.looseIntersections.obstacleTree.AllHitItems(
      Rectangle.mkOnPoints([sNewPosition]),
      (poly) => Curve.PointRelativeToCurveLocation(sNewPosition, poly) !== PointLocation.Outside,
    )) {
      if (s.getELP().has(poly) === false) {
        return false
      }
    }
    for (const t of s.Neighbors) {
      const obstaclesToIgnore = this.metroGraphData.looseIntersections.ObstaclesToIgnoreForBundle(t, s)
      if (!this.metroGraphData.cdtIntersections.EdgeIsLegal_(t.Position, sNewPosition, t.cdtTriangle, obstaclesToIgnore)) return false
    }
    return true
  }

BuildDirection(node: Station): Point {
    const forceInk = this.BuildForceForInk(node)
    const forcePL = this.BuildForceForPathLengths(node)
    const forceR = this.BuildForceForRadius(node)
    const forceBundle = this.BuildForceForBundle(node)
    const force = forceInk.add(forcePL.add(forceR.add(forceBundle)))
    if (force.length < 0.1) {
      return new Point(0, 0)
    }

    return force.normalize()
  }

BuildStepLength(node: Station, direction: Point): number {
    let stepLength: number = SimulatedAnnealing.MinStep
    let costGain: number = this.CostGain(node, node.Position.add(direction.mul(stepLength)))
    if (costGain < 0.01) {
      return 0
    }

    while (2 * stepLength <= SimulatedAnnealing.MaxStep) {
      const newCostGain: number = this.CostGain(node, node.Position.add(direction.mul(stepLength * 2)))
      if (newCostGain <= costGain) {
        break
      }

      stepLength *= 2
      costGain = newCostGain
    }

    return stepLength
  }

CostGain(node: Station, newPosition: Point): number {
    const MInf = -12345678
    const rGain: number = this.costCalculator.RadiusGain(node, newPosition)
    if (rGain < MInf) {
      return MInf
    }

    const bundleGain: number = this.costCalculator.BundleGain(node, newPosition)
    if (bundleGain < MInf) {
      return MInf
    }

    const inkGain: number = this.costCalculator.InkGain(node, newPosition)
    const plGain: number = this.costCalculator.PathLengthsGain(node, newPosition)
    return rGain + inkGain + plGain + bundleGain
  }

BuildForceForInk(node: Station): Point {
    //return new Point(0,0);
    let direction = new Point(0, 0)
    for (const adj of node.Neighbors) {
      const p = adj.Position.sub(node.Position)
      direction = direction.add(p.normalize())
    }

    //derivative
    const force = direction.mul(this.bundlingSettings.InkImportance)
    return force
  }

BuildForceForPathLengths(node: Station): Point {
    // return new Point(0,0);
    let direction = new Point(0, 0)
    for (const mni of this.metroGraphData.MetroNodeInfosOfNode(node)) {
      const metroline = mni.Metroline
      const u: Point = mni.PolyPoint.next.point
      const v: Point = mni.PolyPoint.prev.point
      const p1 = u.sub(node.Position)
      const p2 = v.sub(node.Position)
      direction = direction.add(p1.div(p1.length * metroline.IdealLength))
      direction = direction.add(p2.div(p2.length * metroline.IdealLength))
    }
    // derivative
    const force: Point = direction.mul(this.bundlingSettings.PathLengthImportance)
    return force
  }

BuildForceForRadius(node: Station): Point {
    let direction: Point = new Point(0, 0)
    const idealR: number = node.cachedIdealRadius
    const t: {touchedObstacles: Array<[Polyline, Point]>} = {touchedObstacles: []}
    const res: boolean = this.metroGraphData.looseIntersections.HubAvoidsObstaclesSPNBA(node, node.Position, idealR, t)
    if (!res) {
      EdgeNudger.ShowHubs(this.metroGraphData, null, node, './tmp/hubs.svg', [
        DebugCurve.mkDebugCurveTWCI(255, 1, 'Brown', Intersections.containingPoly),
        DebugCurve.mkDebugCurveTWCI(100, 1, 'Blue', CurveFactory.mkCircle(idealR, node.Position)),
      ])
      throw new Error()
    }
    // throw new Error()
    //Assert.assert(res) // problem here
    for (const d of t.touchedObstacles) {
      const dist: number = d[1].sub(node.Position).length
      //Assert.assert(dist <= idealR)
      const lforce: number = 2 * (1 - dist / idealR)
      const dir: Point = node.Position.sub(d[1]).normalize()
      direction = direction.add(dir.mul(lforce))
    }
    // derivative
    const force: Point = direction.mul(this.bundlingSettings.HubRepulsionImportance)
    return force
  }

BuildForceForBundle(station: Station): Point {
    let direction = new Point(0, 0)
    for (const adjStation of station.Neighbors) {
      const idealWidth = this.metroGraphData.GetWidthSSN(station, adjStation, this.bundlingSettings.EdgeSeparation)
      const t: {closestDist: Array<[Point, Point]>} = {closestDist: []}
      const res = this.metroGraphData.cdtIntersections.BundleAvoidsObstacles(
        station,
        adjStation,
        station.Position,
        adjStation.Position,
        idealWidth / 2,
        t,
      )
      if (!res && false) {
        EdgeNudger.ShowHubs(this.metroGraphData, null, station, './tmp/inside_forbid.svg', [
          DebugCurve.mkDebugCurveTWCI(100, 0.2, 'Blue', LineSegment.mkPP(station.Position, adjStation.Position)),
          DebugCurve.mkDebugCurveTWCI(100, 0.2, 'Red', CurveFactory.mkCircle(2, station.Position)),
          DebugCurve.mkDebugCurveTWCI(100, 0.2, 'Red', CurveFactory.mkCircle(3, adjStation.Position)),
        ])
      }
      //Assert.assert(res) //todo : still unsolved

      for (const d of t.closestDist) {
        const dist = d[0].sub(d[1]).length
        // Debug.//Assert(LessOrEqual(dist, idealWidth / 2));
        const lforce = 2.0 * (1.0 - dist / (idealWidth / 2))
        const dir = d[0].sub(d[1]).normalize().neg()
        direction = direction.add(dir.mul(lforce))
      }
    }

    //derivative
    const force = direction.mul(this.bundlingSettings.BundleRepulsionImportance)

    return force
  }

function RandomPoint(): Point {
  return new Point(1 + 2 * random(), 1 + 2 * random())
}

