function AreOverlapping(rects: Rectangle[]): boolean {
  const rs = rects.map((r) => r.clone())
  for (let i = 0; i < rs.length; i++) {
    rs[i].pad(-0.01)
  }

  for (let i = 0; i < rs.length - 1; i++) {
    for (let j: number = i + 1; j < rs.length; j++) {
      if (rs[i].intersects(rs[j])) {
        return true
      }
    }
  }

  return false
}

